enum StoryType {
  story("Story"),
  qasidah("Poem");

  final String name;
  const StoryType(this.name);
}

class Story {
  final List<String> text;
  final StoryType type;

  const Story({this.type = StoryType.story, required this.text});

  bool get isQasidah => type == StoryType.qasidah;
  List<String> get txt => text;
}

const List<Story> stories = [
  Story(
    text: [
      '''اليتيم من الكتاب العبرات للكاتب مصطفى لطفي المنفلوطي''',
      '''موضوع''',
      '''سكنَ الغرفة العليا من المنزل المجاور لمنزلي من عهد قريب فتًى في التاسعة عشرة أو العشرين من عمره، وأحسب أنه طالبٌ من طلبة المدارس العليا أو الوسطى في مصر، فقد كنت أراه من نافذة غرفة مكتبي، وكانت على كثبٍ من بعض نوافذ غرفته، فأرى أمامي فتًى شاحبًا، نحيلًا، منقبضًا، جالسًا إلى مصباح منير في إحدى زوايا الغرفة، ينظر في كتاب، أو يكتب في دفتر، أو يستظهر قطعةً، أو يُعيد درسًا، فلم أكن أحفل بشيءٍ من أمره.''',
      '''حتى عُدتُ إلى منزلي منذ أيامٍ بعد منتصف ليلةٍ قَرَّةٍ من ليالي الشتاء، فدخلت غرفةَ مكتبي لبعض الشئون، فأشرفتُ عليه، فإذا هو جالسٌ جِلسته تلك أمام مصباحه، وقد أكبَّ بوجهه على دفترٍ منشور بين يديه على مكتبه، فظننتُ أنه لمَّا ألمَّ به من تعب الدرس وآلام السهر، قد عَبِئَتْ بجفنيه سِنةٌ من النوم، فأعجلته من الذهاب إلى فراشه، وسقطت به مكانه، فما رُمْتُ مكاني حتى رفع رأسه، فإذا عيناه مخضلَّتان من البكاء، وإذا صفحة دفتره التي كان مكبًّا عليها قد جرى دمعه فوقها، فمحا من كلماتها ما محا، ومشى ببعض مِدادها إلى بعض، ثم لم يلبث أن عاد إلى نفسه، فتناول قلمه، ورجع إلى شأنه الذي كان فيه.''',
      '''فأحزنني أن أرى في ظلمة ذلك الليل وسكونه هذا الفتى البائس المسكين منفردًا بنفسه في غرفة عارية باردة! لا يتقي فيها عادية البرد بدثارٍ ولا نارٍ، يشكو همًّا من هموم الحياة أو رُزءًا من أرزائها، قبل أن يبلغ سن الهموم والأحزان، من حيث لا يجد بجانبه مواسيًا ولا معينًا.''',
      '''وقلت: «لا بد أن يكون وراء هذا المنظر الضارع الشاحب نفسٌ قريحةٌ معذبةٌ تذوب بين أضلاعه ذوبًا، فيتهافت لها جسمه تهافت الخِباء المقوَّض.»''',
      '''فلم أزل واقفًا مكاني لا أبرحه، حتى رأيته قد طوى كتابه وفارق مجلسه، وأوى إلى فراشه، فانصرفتُ إلى مخدعي، وقد مضى الليل إلا أقله، ولم يبقَ من سواده في صفحة هذا الوجود إلا بقايا أسطر يوشك أن يمتد إليها لسان الصباح فيأتي عليها.''',
      '''ثم لم أزل أراه بعد ذلك في كثيرٍ من الليالي إما باكيًا، أو مُطرِقًا، أو ضاربًا برأسه على صدره، أو منطويًا على نفسه في فراشه يئن أنين الوالهة الثكلى، أو هائمًا في غرفته يذرع أرضها، ويمسح جدرانها، حتى إذا نال منه الجهد سقط على كرسيه باكيًا منتحبًا، فأتوجع له، وأبكي لبكائه، وأتمنى لو استطعتُ أن أُداخله مداخلة الصديق لصديقه، وأستبثه ذات نفسه وأشركه في همِّه، لولا أنني كرهتُ أن أفجأه بما لا يُحب، وأن أهجم منه على سرٍّ ربما كان يؤثر الإبقاء عليه في صدره، وأن يكاتمه الناس جميعًا.''',
      '''حتى أشرفت عليه ليلة أمس بعد هدأةٍ من الليل، فرأيتُ غرفته مظلمةً ساكنة، فظننت أنه خرج لبعض شأنه، ثم لم ألبث أن سمعت في جوف الغرفة أنَّةً ضعيفة مستطيلة، فأزعجني مسمعها، وخيِّل إليَّ، وهي صادرة من أعماق نفسه، كأنني أسمع رنينها في أعماق قلبي، وقلت: «إن الفتى مريض ولا يوجد بجانبه من يقوم بشأنه، وقد بلغ الأمر مبلغ الجد فلا بد لي من المسير إليه.»''',
      '''فتقدَّمتُ إلى خادمي أن يتقدَّمني بمصابيح، حتى بلغتُ منزله، وصعدتُ إلى باب غرفته، فأدركني من الوحشة عند دخولها ما يُدرك الواقف على باب قبر، ويحاول أن يهبطه ليودِّع ساكنه الوداع الأخير.''',
      '''ثم دخلتُ ففتح عينيه عندما أحس بي، وكأنما كان ذاهلًا أو مستغرقًا، فأدهشه أن يرى بين يديه مصباحًا ضئيلًا ورجلًا لا يعرفه، فلبث شاخصًا إليَّ هنيهةً لا ينطق ولا يطرف، فاقتربتُ من فراشه وجلستُ بجانبه، وقلت: «أنا جارك القاطن هذا المنزل، وقد سمعتك الساعة تعالج نفسك علاجًا شديدًا، وعلمت أنك وحدك في هذه الغرفة؛ فعناني أمرك؛ فجئتك علَّني أستطيع أن أكون لك عونًا على شأنك، فهل أنت مريض؟»''',
      '''فرفع يده ببطء، ووضعها على جبهته، فوضعتُ يدي حيث وضعها، فشعرت برأسه يلتهب التهابًا فعلمت أنه محموم، ثم أمررتُ نظري على جسمه فإذا خيالٌ سارٍ لا يكاد يتبينه رائيه، وإذا قميص فضفاض من الجلد يموج فيه بدنه موجًا.''',
      '''فأمرت الخادم أن يأتيني بشرابٍ كان عندي من أشربة الحمى، فجرَّعتُه منه بضع قطرات، فاستفاق قليلًا ونظر إليَّ نظرةً عذبةً صافيةً، وقال: «شكرًا لك.»''',
      '''فقلت: «ما شِكاتُك أيها الأخ؟»''',
      '''قال: «لا أشكو شيئًا.»''',
      '''فقلت: «فهل مرَّ بك زمن طويل على حالك هذه؟»''',
      '''قال: «لا أعلم!»''',
      '''قلت: «أنت في حاجة إلى الطبيب، فهل تأذن لي أن أدعوه إليك لينظر في أمرك؟»''',
      '''فتنهَّد طويلًا ونظر إليَّ نظرةً دامعةً، وقال: «إنما يبغي الطبيبَ من يُؤثر الحياة على الموت!»''',
      '''ثم أغمض عينيه، وعاد إلى ذهوله واستغراقه، فلم أجد بدًّا من دعاء الطبيب رضي أم أبى، فدعوته، فجاء متأفِّفًا متذمِّرًا، يشكو — من حيث يعلم أني أسمع شكواه — إزعاجه من مرقده وتجشيمه خوض الأزقة المظلمة في الليالي الباردة! فلم أحفل بتعريضه؛ لأنني أعلم طريق الاعتذار إليه؛ فجسَّ نبض المريض وهمس في أذني قائلًا: «إن عليلك يا سيدي مشرفٌ على الخطر، ولا أحسب أن حياته تطول كثيرًا إلا إذا كان في علم الله ما لا نعلم.»''',
      '''وجلس ناحيةً يكتب ذلك الأمر الذي يصدره الأطباء إلى عمَّالهم الصيادلة أن يتقاضوا من عبيدهم المرضى ضريبة الحياة، ثم انصرف لشأنه بعدما اعتذرتُ إليه ذلك الاعتذار الذي يؤثره ويرضاه.''',
      '''فأحضرتُ الدواء، وقضيت بجانب المريض ليلةً ليلاء، ذاهلة النجم، بعيدة ما بين الطرفين، أسقيه الدواء مرةً، وأبكي عليه أخرى، حتى انبثق نور الفجر؛ فاستفاق ودار بعينيه حول فراشه حتى رآني، فقال: «أنت هنا؟»''',
      '''قلت: «نعم، وأرجو أن تكون أحسن حالًا من ذي قبل.»''',
      '''قال: «أرجو أن أكون كذلك.»''',
      '''قلت: «هل تأذن لي يا سيدي أن أسألك من أنت؟ وما مقامك وحدك في هذا المكان؟ وهل أنت غريب في هذا البلد أو أنت من أهليه؟ وهل تشكو داءً ظاهرًا أو همًّا باطنًا؟»''',
      '''قال: «أشكوهما معًا.»''',
      '''قلت: «فهل لك أن تحدِّثني بشأنك وتفضي إليَّ بهمك كما يفضي الصديق إلى صديقه، فقد أصبحت معنيًّا بأمرك عنايتك بنفسك؟»''',
      '''قال: «هل تعدني بكتمان أمري إن قَسَمَ الله لي الحياة، وبإمضاء وصيَّتي إن كانت الأخرى؟»''',
      '''قلت: «نعم.»''',
      '''قال: «قد وثقت بوعدك، فإن من يحمل في صدره قلبًا شريفًا مثل قلبك لا يكون كاذبًا ولا غادرًا.''',
      '''أنا فلان بن فلان، مات أبي منذ عهدٍ بعيد، وتركني في السادسة من عمري فقيرًا معدِمًا لا أملك من متاع الدنيا شيئًا، فكفلني عمي فلان، فكان خير الأعمام، وأكرمهم، وأوسعهم برًّا وإحسانًا، وأكثرهم عطفًا وحنانًا، فقد أنزلني من نفسه منزلةً لم ينزلها أحدًا من قبلي غير ابنته الصغيرة، وكانت في عمري أو أصغر مني قليلًا، وكأنما سرَّه أن يرى لها بجانبها أخًا بعدما تمنى على الله ذلك زمنًا طويلًا فلم يدرك أمنيته، فعُنِيَ بي عنايته بها، وأدخلنا المدرسة في يوم واحد، فأنِستُ بها أنس الأخ بأخته، وأحببتها حبًّا شديدًا، ووجدت في عشرتها من السعادة والغبطة ما ذهب بتلك الغضاضة التي كانت لا تزال تعاود نفسي بعدَ فَقْدِ أبويَّ من حينٍ إلى حين.''',
      '''فكان لا يرانا الرائي إلا ذاهبَيْن إلى المدرسة أو عائدَيْن منها، أو لاعبَيْن في فناء المنزل، أو مُرْتَاضَيْن في حديقته، أو مجتمعَيْن في غرفة المذاكرة، أو متحدِّثَيْن في غرفة النوم، حتى جاء يوم حجابها فلزمت خِدرَها واستمررتُ في دراستي.''',
      '''ولقد عقد الود بين قلبي وقلبها عقدًا لا يحله إلا رَيْبُ المنون، كنت لا أرى لذة العيش إلا بجوارها، ولا أرَى نُورَ السعادة إلا في فجر ابتساماتها، ولا أؤثرُ على ساعة أقضيها بجانبها جميع لذات العيش ومَسَرَّات الحياة، وما كنت أشاء أن أرى خَصْلة من خصال الخير في فتاة من: أدب، أو ذكاءٍ، أو حلمٍ، أو رحمةٍ، أو عفَّةٍ، أو شرفٍ، أو وفاءٍ إلَّا وجدتها فيها.''',
      '''وإني أستطيع، وأنا في هذه الظلمة الحالكة من الهموم والأحزان، أن أرى على البعد تلك الأجنحة النورانية البيضاء من السعادة التي كانت تُظللنا معًا أيام طفولتنا؛ فتشرق لها نفسانا إشراق الرَّاح في كأسها.''',
      '''وأن أرى تلك الحديقة الغنَّاء التي كانت مراح لذاتنا ومسرح آمالنا وأحلامنا، كأنها حاضرة بين يدي أرى لَأْلَاء مائها، ولمعان حَصْبَائها، وأفانين أشجارها، وألوان أزهارها.''',
      '''وتلك القاعدة الحجرية التي كنا نقتعدها منها طرفي النهار، فنجتمع على حديثٍ نتجاذبه، أو طاقةٍ نُؤلِّف بين أزهارها، أو كتابٍ نُقَلِّب صفحاته، أو رسم نتبارَى في إتقانه.''',
      '''وتلك الخمائل الخضراء التي نلجأ إلى ظلالها كلما فرغنا من شوط من أشواط المسابقة، فنشعر بما تشعر به أفراخ الطيور اللاجئة إلى أحضان أمهاتها.''',
      '''وتلك الحفائر الصغيرة التي نحتفرها ببعض الأعواد على شاطئ الجداول والغُدْرَان فنملؤها ماءً، ثم نجلس حولها لنصطاد أسماكها التي ألقيناها فيها بأيدينا؛ فنطرب إن ظَفِرْنا بشيءٍ منها كأنَّا قد ظفرنا بغُنمٍ عظيم.''',
      '''وتلك الأقفاص الذهبية البديعة التي كنا نربي فيها عصافيرنا وطيورنا، ثم نقضي الساعات الطوال بجانبها نعجب بمنظرها ومنظر مناقيرها الخضراء، وهي تحسو الماء مرةً وتلتقط الحب أخرى، ونناديها بأسمائها التي سميناها بها، فإذا سمعنا صفيرها وتغريدها ظننا أنها تُلَبِّي نداءنا.''',
      '''ولا أعلم هل كان ما كنت أُضْمِرْهُ في نفسي لابنةِ عمي ودًّا وإخاءً، أو حبًّا وغرامًا؟ ولكنني أعلم أنه كان بلا أمل، ولا رجاء، فما قلت لها يومًا إني أحبها؛ لأني كنت أضنُّ بها — وهي ابنة عمي ورفيقة صباي — أن أكون أوَّل فاتح لهذا الجرح الأليم في قلبها، ولا قدرت في نفسي يومًا من الأيام أن أَصِل أسباب حياتي بأسباب حياتها؛ لأني كنت أعلم أن أبويها لا يسخوان بمثلها على فتى بائسٍ فقيرٍ مثلي، ولا حاولت في ساعةٍ من الساعات أن أتَسَقَّط منها ما يطمع في مثله المحبون المتسقِّطون؛ لأني كنت أجلُّها عن أن أنزل بها إلى مثل ذلك، ولا فكرت يومًا أن أستشف من وراء نظراتها خبيئة نفسها لأعلم أي المنزلتين أنزلها من قلبها: أمنزلة الأخ فأقنع منها بذلك، أم منزلة الحبيب، فأستعين بإرادتها على إرادة أبويها؟ بل كان حبي لها حب الراهب المتبتل صورة العذراء الماثلة بين يديه في صومعته، يعبدها ولا يتطلع إليها!''',
      '''ولم يزل هذا شأني وشأنها، حتى نزلت بعمي نازلةٌ من المرض لم تنشب أن ذهبت به إلى جوار ربه، وكان آخر ما نطق به في آخر ساعات حياته أن قال لزوجته، وكان يُحسِن بها ظنًّا: لقد أعجلني الموت عن النظر في شأن هذا الغلام، فكوني له أمًّا كما كنتُ له أبًا، وأوصيك ألا يفقد مني بعد موتي إلا شخصي.''',
      '''فما مرت أيام الحداد حتى رأيت وجوهًا غير الوجوه، ونظراتٍ غير النظرات، وحالًا غريبة لا عهد لي بمثلها من قبل، فتَداخَلَني الهمُّ واليأس، ووقع في نفسي للمرة الأولى في حياتي أنني قد أصبحت في هذا المنزل غريبًا، وفي هذا العالم طريدًا.''',
      '''فإني لجالسٌ في غرفتي صبيحة يومٍ إذ دخلت عليَّ الخادم، وكانت امرأةً من النساء الصالحات المخلصات، فتقدَّمتْ نحوي خجلة متعثرة، وقالت: قد أمرتني سيدتي أن أقول لك يا سيدي إنها قد عزمت على تزويج ابنتها في عهد قريب، وإنها ترى أن بقاءك بجانبها بعد موت أبيها وبلوغكما هذه السن التي بلغتماها ربما يُريبها عند خطيبها، وإنها تريد أن تتخذ للزوجين مسكنًا هذا الجناح الذي تسكنه من القصر، فهي تريد أن تتحول إلى منزلٍ آخر تختاره لنفسك من بين منازلها، على أن تقوم لك فيه بجميع شأنك، وكأنك لم تفارقها.''',
      '''فكأنما عمدتْ إلى سهمٍ رائشٍ فأصْمَتْ به كبدي، إلا أنني تماسكت قليلًا ريثما قلت لها: «سأفعل إن شاء الله ولا أَحَبَّ إليَّ من ذلك.» فانصرفتْ لشأنها، فخلوتُ بنفسي ساعة أطلقت فيها السبيل لعَبَراتي، ما شاء الله أن أطلقها، حتى جاء الليل، فعمدتُ إلى حقيبتي فأودعتُها ثيابي وكتبي، وقلت في نفسي: «قد كان كل ما أسعد به في هذه الحياة أن أعيش بجانب ذلك الإنسان الذي أحببته وأحببت نفسي من أجله، وقد حيل بيني وبينه، فلا آسف على شيءٍ بعده.»''',
      '''ثم انسللتُ من المنزل انسلالًا من حيث لا يشعر أحدٌ بما كان، ولم أتزوَّد من ابنة عمي قبل الرحيل غير نظرة واحدة ألقيتها عليها من خلال كِلَّتِهَا وهي نائمة في سريرها، فكانت آخر عهدي بها:''',
      '''لَعَمْرُكَ مَا فَارَقْتُ بَغْدَادَ عَنْ قِلًى''',
      '''لَو انَّا وَجَدْنَا مِنْ فِرَاقٍ لَهَا بُدَّا''',
      '''كَفَى حُزْنًا أَنْ رُحْتُ لَمْ أَسْتَطِعْ لَهَا''',
      '''وَدَاعًا، وَلَمْ أُحْدِثْ بِسَاكِنِهَا عَهْدَا''',
      '''وهكذا فارقتُ المنزل الذي سعدتُ فيه حقبةً من الزمان فِراقَ آدم جنَّته، وخرجتُ منه شريدًا طريدًا، حائرًا ملتاعًا، قد اصطلحت عليَّ الهموم والأحزان، فراق لا لقاء بعده، وفقر لا سادَّ لخلَّته، وغربة لا أجد عليها من أحد من الناس مواسيًا ولا معينًا.''',
      '''وكانت معي صُبابةٌ من مالٍ قد بقيتْ في يدي من آثار تلك النعمة الذاهبة، فاتخذتُ هذه الحجرة العارية في هذه الطبقة العليا مسكنًا، فلم أستطع البقاء فيها ساعةً واحدة، فأزمعتُ الرحيل إلى حيث أجد في فضاء الله ومنفسح آفاقه علاج نفسي من همومها وأحزانها، فرحلت رحلة طويلة، قضيت فيها بضعة أشهر، لا أهبط بلدةً حتى تنازعني نفسي إلى أخرى، ولا تطلع عليَّ الشمس في مكانٍ حتى تغرب عني في غيره، حتى شعرت في آخر الأمر بسكونٍ في نفسي يشبه سكون الدمع المعلق في محجر العين، لا يفيض ولا يغيض.''',
      '''فقنعت بذلك، وكان ميعاد الدراسة السنوية قد حان، فعدت، وقد استقر في نفسي أن أعيش في هذا العالم منفردًا كمُجتمِع، وغائبًا كحاضرٍ، وبعيدًا كقريب، وأن ألهو بشأن نفسي عن كل شأنٍ سواه، وأن أستعين على نسيان الماضي باجتناب مواطنه ومظاهره.''',
      '''فلزمتُ غرفتي ومدرستي أُداول بينهما لا أفارقهما، ولم يبقَ أثرٌ لذلك العهد القديم في نفسي إلا نزوات تعاود قلبي من حين إلى حين، فأستعين عليها بقطراتٍ من الدمع أسكبها من جفني في خلوتي من حيث لا يعلم إلا الله ما بي، فأجد برد الراحة في صدري.''',
      '''لبثت على ذلك برهةً من الزمان، حتى عدتُ بالأمس إلى تلك الفضلة التي كانت في يدي من المال، فإذا هي ناضبةٌ أو موشكة، وكنتُ مأخوذًا بأن أهيِّئ لنفسي عيشًا مستقلًّا، وأن أؤدي للمدرسة قسطًا من أقساطها، والمدرسة في هذا البلد حانوتٌ قاسٍ لا تُباع فيه السلعة نسيئةً، والعلم في هذه الأمة مرتزقٌ يَرتزق منه المرتزقون، لا منحةٌ يمنحها المحسنون، فأهمتني نفسي، وعلمت أني مشرف على الخطر، ولا أعرف سبيلًا إلى القوت بوجه ولا حيلة.''',
      '''فعمدتُ إلى كتبي، فاستبقيت منها ما لا غنًى لي عنه، وحملت سائرها إلى سوق الوراقين، فعرضته هناك يومًا كاملًا، فلم أجد من يبلغ به في المساومة ربع ثمنه؛ فعدت به حزينًا وما على وجه الأرض أحدٌ أذل مني ولا أشقى!''',
      '''فلما بلغتُ باب المنزل رأيت في فنائه امرأةً تُسائل أهل البيت عني، فتبيَّنتُها فإذا هي الخادم التي كانت تخدمني في منزل عمي.''',
      '''فقلت: «فلانه؟»''',
      '''قالت: «نعم.»''',
      '''قلت: «ماذا تريدين؟»''',
      '''قالت: «لي إليك كلمة فائذن لي.»''',
      '''فصعدتُ معها إلى غرفتي، فلما خلونا قلت: «هاتِ.»''',
      '''قالت: «مرَّت بي ثلاثة أيام وأنا أفتش عنك في كل مكانٍ، فلم أجد من يدلني عليك حتى وجدتك اليوم بعد اليأس منك.»''',
      '''ثم انفجرت باكيةً بصوتٍ عالٍ؛ فراعني بكاؤها وخفت أن يكون قد حلَّ بالبيت الذي أحبه بأسٌ.''',
      '''فقلت: «ما بكاؤك؟»''',
      '''قالت: «أما تعلم شيئًا من أخبار بيت عمك؟»''',
      '''قلت: «لا، فما أخباره؟»''',
      '''فمدَّت يدها إلى ردائها وأخرجت من أضعافه كتابًا مغلقًا، فتناولتُه منها، ففضضتُ غلافه، فإذا هو بخط ابنة عمي، فقرأتُ فيه هذه الكلمة لا أزال أحفظها حتى الساعة: «إنك فارقتني ولم تودعني، فاغتفرتُ لك ذلك، فأما اليوم وقد أصبحتُ على باب القبر، فلا أغتفر لك ألا تأتي إليَّ لتودعني الوداع الأخير.»''',
      '''فألقيت الكتاب من يدي، وابتدرت الباب مسرعًا، فتعلَّقتِ الخادم بثوبي، وقالت: «أين تريد يا سيدي؟»''',
      '''قلت: «إنها مريضة، ولا بد لي من المسير إليها.»''',
      '''فصمتتْ لحظةً ثم قالت بصوتٍ خافتٍ مرتعش: «لا تفعل يا سيدي، فقد سبقك القضاء إليها!»''',
      '''هنالك شعرتُ أن قلبي قد فارق موضعه إلى حيث لا أعلم له مكانًا، ثم دارت بي الأرض الفضاء دورةً سقطتُ على أثرها في مكاني لا أشعر بشيءٍ مما حولي، فلم أفق إلا بعد حين، ففتحت عيني فإذا الليل قد أظلني، وإذا الخادم لا تزال تبكي وتنتحب، فدنوت منها، وقلت: «أيتها المرأة، أحقٌّ ما تقولين؟»''',
      '''قالت: «نعم.»''',
      '''قلت: «قُصِّي عليَّ كل شيءٍ.»''',
      '''فأنشأتْ تقول: «إن ابنة عمك يا سيدي لم تنتفع بنفسها بعد رحيلك، فقد سألتني في اليوم الذي رحلتَ فيه عن سبب رحيلك، فحدَّثتُها حديث الرسالة التي حملتُها إليك من زوجة عمك.''',
      '''فلم تزد على أن قالت: «وماذا يكون مصير هذا البائس المسكين؟ إنهم لا يعلمون من أمره ولا من أمري شيئًا، ثم لم يَجْرِ ذكرك بعد ذلك على لسانها بخير ولا بشر، كأنما كانت تعالج في نفسها ألمًا ممضًّا.»''',
      '''وما هي إلا أيام قلائل حتى سرى داء نفسها إلى جسمها، فاستحالت حالها، غاض ماء جمالها، وانطفأت تلك الابتسامات العذبة التي كانت لا تُفارق ثغرها، ثم سقطت على فراشها مريضةً لا تبلُّ يومًا حتى تنتكس أيامًا، فراع أمَّها أمرُها، وورد عليها ما قطعها عن ذكر العرس والعروس والخطبة والخطيب، وكانت لا تزال تهتف بذلك نهارها وليلها، فلم تدع طبيبًا ولا عائدًا إلا فزعت إليه أمرها، فما أغنى العائد ولا الطبيب! وأصبحت الفتاة تدنو من القبر رويدًا رويدًا.''',
      '''فبينما أنا ساهرةٌ بجانب فراشها منذ ليالٍ إذ شعرت بها تتحرك في مضجعها، فدنوت منها، فأشارت إليَّ أن آخذ بيدها، ففعلتُ، فاستوت جالسةً وقالت: «في أي ساعة نحن من الليل؟»''',
      '''قلت: «في الهزيع الأخير منه.»''',
      '''قالت: «أأنت وحدك هنا؟»''',
      '''قلت: «نعم، فقد هجع أهل البيت جميعًا.»''',
      '''قالت: «ألا تعلمين أين مكان ابن عمي الآن؟»''',
      '''فعجبتُ لكلمةٍ لم أسمعها منها قبل اليوم، وقلت: «بلى يا سيدتي أعلم مكانه.»''',
      '''وما كنتُ أعلم شيئًا، ولكني أشفقتُ على هذا الخيط الرقيق الباقي في يدها من الأمل أن ينقطع فينقطع بانقطاعه آخر خيط من خيوط أجلها، فقالت: «ألا تستطيعين أن تحملي إليه رسالةً مني من حيث لا يعلم أحدٌ بشأني؟»''',
      '''قلت: «لا أَحَبَّ إليَّ من ذلك يا سيدتي.»''',
      '''فأشارت أن آتيها بمحبرتها، فجئتُها بها، فكتبتْ إليك هذا الكتاب الذي تراه، فلما أصبح الصباح خرجتُ أسائل الناس عنك في كل مكان، وأتصفَّح وجوه الغادين والرائحين علَّني أراك وأرى مَن يهديني إليك، فلم أظفر بطائلٍ حتى انحدرت الشمس إلى مغربها، فعدت إلى المنزل وقد مضى شطر من الليل، فما بلغتُهُ حتى سمعتُ الناعية، فعلمت أن السهم قد بلغ المقتل، وأن تلك الوردة الناضرة التي كانت تملأ الدنيا جمالًا وبهاءً قد سقطتْ آخر ورقةٍ من ورقاتها، فحزنتُ عليها حزن الثاكل على وحيدها، وما رُئي مثل يومها يومٌ كان أكثر باكيةً وباكيًا!''',
      '''وكان أكبر ما أهمني من أمرها، أنَّ كل ما كانت ترجوه في الساعة الأخيرة من ساعات حياتها أن تراك، ففاتها ذلك وسقطت دون أمنيتها، فلم أزل كاتمةً أمر الرسالة في نفسي، ولم أزل أتطلب السبيل إليك حتى وجدتك.»''',
      '''فشكرتُ لها صنيعها وآذنتها بالانصراف فانصرفتْ، فما انفردتُ بنفسي حتى شعرتُ أن سحابةً سوداء تهبط فوق عيني شيئًا فشيئًا حتى احتجب عن ناظري كل شيءٍ، ثم لا أعلم ماذا تم بعد ذلك حتى رأيتُك.»''',
      '''وما وصل من حديثه إلى هذا الحد، حتى زفر زفرةً خِلْتُ أن كبده قد ارفَضَّت، وأن هذه أفلاذها، فدنوت منه، وقلت: «ما بك يا سيدي؟»''',
      '''قال لي: «إني أطلب دمعةً واحدةً أتفرج بها مما أنا فيه فلا أجدها!»''',
      '''ثم صمتَ ساعةً طويلة، فشعرتُ أنه يهمهم ببعض كلماتٍ، فأصغيت إليه، فإذا هو يقول: «اللهم إنك تعلم أني غريبٌ في هذه الدنيا، لا سند لي فيها ولا عضد، وأني فقير لا أملك من متاع الحياة ما أعود به على نفسي، وأني عاجزٌ مستضعفٌ لا أعرف السبيل إلى بابٍ من أبواب الرزق بوجهٍ ولا حيلة، وأن الضربة التي أصابت قلبي قد سحقته سحقًا فلم يبقَ فيه حتى الذَّمَاء، وإني أستحي منك أن أمد يدي إلى هذه النفس التي أودعتها بيدك بين جنبي فأنتزعها من مكانها، فتولَّ أنت أمرها بيدك، واسترد وديعتك إليك، وانقلها إلى دار كرامتك، فنِعْمَ الدار دارك، ونِعْمَ الجوار جوارك.»''',
      '''ثم أمسك رأسه بيده، كأنما يحاول أن يحبسه عن الفرار، وقال بصوت ضعيف خافت: «أشعر برأسي يحترق احتراقًا، وقلبي يذوب ذوبًا، لا أحسبني باقيًا على هذا، فهل تعدني أن تدفنني معها في قبرها وتدفن معي كتابها إن قضى الله فيَّ قضاءه؟»''',
      '''قلت: «نعم، وأسأل الله لك السلامة!»''',
      '''قال: «الآن أموت طيب النفس عن كل شيء.»''',
      '''ثم انتفض انتفاضة فاضت نفسه فيها!''',
      '''لقد هوَّن وجدي على هذا البائس المسكين، أني استطعت إمضاء وصيته كما أراد، فسعيت في دفنه مع ابنة عمه، ودفنت معه تلك الرسالة التي دعته فيها أن يوافيها، فعجز عن أن يلبي نداءها حيًّا فلبَّاها ميتًا.''',
      '''وهكذا اجتمع تحت سقفٍ واحد ذانِكَ الصديقان الوفيان، اللذان ضاق بهما في حياتهما فضاءُ القصر، فوسعتهما بعد موتهما حفرة القبر.''',
    ],
  ),
  Story(
    text: [
      '''تَخْطِيطُ الْبِرْكَةِ من كتاب مُغَامَرَاتُ الْقُنْدُسِ بادي''',
      '''الفصل الثاني - تَخْطِيطُ الْبِرْكَةِ''',
      '''انْهَمَكَ الْقُنْدُسُ بادي فِي تَقْطِيعِ الْأَشْجَارِ مِنْ أَجْلِ السَّدِّ الَّذِي كَانَ يَنْوِي بِنَاءَهُ؛ فَكَانَ قَدْ تَعَلَّمَ فِي الْغَابَاتِ الشَّمَالِيَّةِ الَّتِي أَتَى مِنْهَا إِلَى الْغَابَةِ الْخَضْرَاءِ كُلَّ شَيْءٍ عَنْ تَقْطِيعِ الْأَشْجَارِ وَإِقَامَةِ السُّدُودِ وَحَفْرِ الْقَنَوَاتِ وَبِنَاءِ الْبُيُوتِ. فَقَدْ كَانَ وَالِدَا بادي عَلَى دِرَايَةٍ كَبِيرَةٍ بِمُجْرَيَاتِ الْأُمُورِ فِي عَالَمِ الْقَنَادِسِ، وَكَانَ بادي سَرِيعَ التَّعَلُّمِ؛ لِذَا كَانَ يَعْلَمُ الْآنَ مَا يَجِبُ أَنْ يَقُومَ بِهِ وَكَيْفِيَّةَ الْقِيَامِ بِهِ عَلَى أَكْمَلِ وَجْهٍ. فَكَمَا تَعْلَمُونَ، يُهْدِرُ الْكَثِيرُ مِنَ النَّاسِ الْوَقْتَ وَالْجُهْدَ فِي الْقِيَامِ بِالْأَعْمَالِ عَلَى النَّحْوِ الْخَاطِئِ، بِحَيْثُ يُضْطَرُّونَ إِلَى الْقِيَامِ بِهَا مِنْ جَدِيدٍ. فَهُمْ يَنْسَوْنَ أَنْ يَتَأَكَّدُوا مِنْ أَنَّهُمْ عَلَى صَوَابٍ؛ وَمِنْ ثَمَّ يَمْضُونَ قُدُمًا حَتَّى يَكْتَشِفُوا أَنَّهُمْ مُخْطِئُونَ، وَيَضِيعُ عَمَلُهُمْ كُلُّهُ سُدًى.''',
      '''وَلَكِنَّ الْقُنْدُسَ بادي لَيْسَ مِنْ أُولَئِكَ النَّاسِ. فَبادي لَمْ يَكُنْ أَبَدًا لِيَثِبَ فِي النَّبْعِ مُنْحَدِرِ الْجَانِبَيْنِ دُونَ أَنْ يَتَرَيَّثَ، مِثْلَمَا يَفْعَلُ الْجَدُّ ضفدع. وَالْآنَ أَخَذَ يَنْتَقِي الْأَشْجَارَ الَّتِي سَوْفَ يُقَطِّعُهَا بِعِنَايَةٍ. فَلَمْ يَكُنْ لَدَيْهِ وَقْتٌ يُضِيعُهُ فِي تَقْطِيعِ شَجَرَةٍ لَنْ تَكُونَ مُنَاسِبَةً لَهُ تَمَامًا بَعْدَمَا تَسْقُطُ. فَعِنْدَمَا تَأَكَّدَ مِنْ أَنَّهَا مُنَاسِبَةٌ، نَظَرَ إِلَى قِمَّتِهَا لِيَعْرِفَ إِذَا كَانَتْ — بَعْدَ أَنْ يُقَطِّعَهَا — سَتَسْقُطُ بَعِيدًا عَنِ الْأَشْجَارِ الْأُخْرَى؛ فَقَدْ تَعَلَّمَ ذَلِكَ عِنْدَمَا كَانَ صَغِيرًا طَائِشًا. فَقَدْ كَانَ يَذْكُرُ شُعُورَهُ بَعْدَمَا عَمِلَ بِكَدٍّ شَدِيدٍ فِي تَقْطِيعِ شَجَرَةٍ كَبِيرَةٍ، وَنَبَّهَ جَمِيعَ أَصْدِقَائِهِ حَتَّى يُخْلُوا الطَّرِيقَ لِكَيْلَا يَتَعَرَّضُوا لِلْأَذَى إِثْرَ سُقُوطِهَا، ثُمَّ لَمْ تَسْقُطْ مِنَ الْأَسَاسِ؛ لِأَنَّ قِمَّتَهَا اشْتَبَكَتْ بِشَجَرَةٍ أُخْرَى. فَشَعَرَ بِخِزْيٍ بَالِغٍ لَمْ يَسْتَطِعِ التَّغَلُّبَ عَلَيْهِ فَتْرَةً طَوِيلَةً.''',
      '''فَبَاتَ الْآنَ يَتَأَكَّدُ أَنَّ الشَّجَرَةَ سَتَسْقُطُ بَعِيدًا وَحَيْثُمَا يُرِيدُهَا تَمَامًا. ثُمَّ جَلَسَ عَلَى سَاقَيْهِ الْخَلْفِيَّتَيْنِ، مُرْتَكِزًا عَلَى ذَيْلِهِ الْعَرِيضِ كَدِعَامَةٍ، وَبَدَأَتْ رُقَاقَاتُ الْخَشَبِ تَتَطَايَرُ بِفِعْلِ أَسْنَانِهِ. فَكَمَا تَعْلَمُونَ، يَمْلِكُ بادي أَسْنَانًا مُمْتَازَةً لِلْغَايَةِ لِتَقْطِيعِ الْأَشْجَارِ، فَهِيَ طَوِيلَةٌ وَعَرِيضَةٌ وَحَادَّةٌ. كَانَ يَبْدَأُ بِقَضْمَةٍ غَائِرَةٍ، ثُمَّ أُخْرَى أَسْفَلَهَا بِمَسَافَةٍ قَصِيرَةٍ، ثُمَّ يَقْتَلِعُ قِطْعَةَ الْخَشَبِ الصَّغِيرَةَ الْوَاقِعَةَ بَيْنَ الْقَضْمَتَيْنِ. وَعِنْدَمَا يَتَوَغَّلُ فِي تَقْطِيعِ الشَّجَرَةِ مِنْ جَانِبٍ وَاحِدٍ يُؤَدِّي إِلَى سُقُوطِ الشَّجَرَةِ فِي ذَلِكَ الِاتِّجَاهِ؛ يُكْمِلُ عَمَلَهُ حَتَّى يَبْلُغَ الْجَانِبَ الْآخَرَ. وَبِمُجَرَّدِ أَنْ تَبْدَأَ الشَّجَرَةُ فِي التَّمَايُلِ وَيَتَأَكَّدَ مِنْ أَنَّهَا سَتَسْقُطُ، يُهْرَعُ مُبْتَعِدًا عَنِ الْخَطَرِ. وَكَانَ يُحِبُّ مُشَاهَدَةَ تِلْكَ الْأَشْجَارِ الْعَالِيَةِ وَهِيَ تَمِيلُ إِلَى الْأَمَامِ بِبُطْءٍ، ثُمَّ أَسْرَعَ فَأَسْرَعَ؛ حَتَّى تَرْتَطِمَ بِالْأَرْضِ مُحْدِثَةً صَوْتًا مُدَوِّيًا.''',
      '''وَبِمُجَرَّدِ أَنْ تَسْقُطَ، يُجَرِّدُهَا مِنْ فُرُوعِهَا إِلَى أَنْ تَصِيرَ الْأَشْجَارُ كَأَعْمِدَةٍ طَوِيلَةٍ. لَمْ يَكُنْ ذَلِكَ بِالْعَمَلِ الشَّاقِّ لَهُ؛ فَقَدْ كَانَ بِاسْتِطَاعَتِهِ اقْتِلَاعُ فَرْعِ شَجَرَةٍ كَبِيرٍ بِقَضْمَةٍ وَاحِدَةٍ. وَكَثِيرٌ مِنَ الْأَشْجَارِ كَانَ يَتْرُكُ قِمَمَهَا الْمُورِقَةَ، وَعِنْدَمَا يَنْتَهِي مِنْ تَشْذِيبِ الْفُرُوعِ بِمَا يُلَائِمُهُ وَيُقَطِّعُهَا إِلَى أَطْوَالٍ مُنَاسِبَةٍ، يَشُدُّهَا وَيَجْذِبُهَا إِلَى الْمَكَانِ الَّذِي يَنْتَوِي بِنَاءَ السَّدِّ فِيهِ.''',
      '''وَهُنَاكَ يَضَعُ الْجُذُوعَ جَنْبًا إِلَى جَنْبٍ، وَلَيْسَ بِعَرْضِ الْجَدْوَلِ الضَّاحِكِ كَالْجِسْرِ، وَإِنَّمَا يَضَعُهَا بِحَيْثُ تَكُونُ أَطْرَافُهَا الْكَبِيرَةُ مُتَّجِهَةً إِلَى أَعْلَى الْجَدْوَلِ الضَّاحِكِ، الَّذِي كَانَ عَرِيضًا إِلَى حَدٍّ كَبِيرٍ وَلَكِنْ ضَحْلًا فِي تِلْكَ الْبُقْعَةِ. وَلِكَيْ يَحُولَ دُونَ طَفْوِ الْجُذُوعِ بَعِيدًا، كَانَ يُدَحْرِجُ الْحَصَى وَيُكَوِّمُ الطِّينَ عَلَى أَطْرَافِهَا الْمُورِقَةِ. وَرَاحَ يَرُصُّ تِلْكَ الْجُذُوعَ حَتَّى بَدَأَ الْمَاءُ يَرْتَفِعُ عَلَى جَانِبَيِ النَّهْرِ. ثُمَّ جَرَّ الْمَزِيدَ مِنَ الْجُذُوعِ وَكَوَّمَهَا فَوْقَ الْأُولَى وَحَشَرَ عِصِيًّا قَصِيرَةً بَيْنَهَا بِالْعَرْضِ.''',
      '''وَطَوَالَ الْوَقْتِ كَانَ الْجَدْوَلُ الضَّاحِكُ يُوَاجِهُ صُعُوبَةً مُتَزَايِدَةً فِي التَّدَفُّقُ، فَصَارَتْ ضِحْكَتُهُ الْمُبْتَهِجَةُ أَقَلَّ بَهْجَةً وَفِي النِّهَايَةِ تَوَقَّفَتْ؛ لِأَنَّ الْمِيَاهَ لَمْ تَسْتَطِعِ الْمُرُورَ عَبْرَ كُلِّ تِلْكَ الْجُذُوعِ وَالْعِصِيِّ بِالسُّرْعَةِ الْكَافِيَةِ. وَحِينَئِذٍ قَرَّرَ سُكَّانُ الْبِرْكَةِ الْبَاسِمَةِ الصِّغَارُ أَنَّهُ آنَ الْأَوَانُ أَنْ يَعْرِفُوا مَا يَفْعَلُهُ بادي تَحْدِيدًا، فَانْطَلَقُوا إِلَى أَعْلَى مَجْرَى الْجَدْوَلِ الضَّاحِكِ، تَارِكِينَ خَلْفَهُمُ الْجَدَّ ضفدع وَالضَّفَادِعَ الصَّغِيرَةَ فَحَسْبُ فِي الْبِرْكَةِ الْبَاسِمَةِ، الَّتِي سَتُفَارِقُهَا الْبَسْمَةُ لِبُرْهَةٍ. ''',
    ],
  ),

  /* Story(text: [
    '''القُبلة للكاتب أنطون تشيخوف''',
    '''في ۲۰ مايو، وفي الساعة الثامنة مساءً توقفتْ جميع البطاريات الست من لواء «س» المدفعية الاحتياطي، التي كانت متجهةً إلى المعسكر، للمبيت في قرية ميستيتشكي. وفي أُوار الهَرْج، عندما كان بعض الضباط يروحون ويجيئون قرب المدافع، بينما كان البعض الآخر، وقد تجمَّعوا في الميدان قرب سور الكنيسة، يستمعون إلى تقارير مسئولي الإيواء، ظهر من وراء الكنيسة فارس في زيٍّ مدنيٍّ وعلى متن حصان غريب. كان حصانًا كُمَيتًا، صغيرًا، بعنق جميل وذيل قصير، ولم يكن يسير في خط مستقيم، بل منحرف، ويأتي بحركات قصيرة راقصة بقوائمه، كأنما كان أحد ما يضربه بالسوط عليها. وعندما اقترب الفارس من الضباط رفع قبعته وقال: صاحب السعادة اللفتنانت جنرال فون … رابيك، الإقطاعي المحلي، يدعو السادة الضباط للحضور إليه حالًا لتناول الشاي.''',
    '''وانحنى الحصان، ورقص، وتراجع بجنبه إلى الخلف، ورفع الفارس قُبعته مرةً أخرى، وبعد لحظة كان قد اختفى مع حصانه الغريب وراء الكنيسة.''',
    '''ودمدم بعض الضباط بتذمُّر وهم ينصرفون إلى مساكنهم: الشيطان يعلم ما هذا! نريد أن ننام، بينما يأتينا هذا الفون … رابيك بشايه! ما الداعي؟ وأي شاي الآن!''',
    '''وتذكَّر ضُباطُ البطاريات الست على الفور حادث العام الماضي، عندما وُجهت إليهم الدعوة في أثناء المناورات، هم وضباط أحد ألوية القوزاق، بمثل هذه الطريقة، لتناول الشاي عند إقطاعي كونت، عسكري سابق. واستقبلهم الكونت المِضياف البشوش برِقة، وأطعمهم وسقاهم، ولم يدَعهم يذهبون إلى القرية للنوم بل استبقاهم للمبيت في داره. وكان كل هذا بالطبع حسنًا، بل ليس هناك أفضل من ذلك، ولكن المصيبة أن فرحة العسكري المتقاعد بالضباط الشبان فاقت كل الحدود، فظل حتى الفجر يروي للضباط مشاهد من ماضيه الطيب، وطاف بهم على الغرف وهو يعرض عليهم لوحاته الثمينة والرسوم القديمة والأسلحة النادرة، وقرأ لهم رسائل خطيةً من شخصيات كبيرة، أمَّا الضباط المعذَّبون المُنهَكون فكانوا يستمعون إليه وينظرون إلى معروضاته وهم يتحرَّقون شوقًا إلى الأسرة، ويُخفون بحذر تثاؤباتهم في أكمامهم. وعندما أطلق المُضيِّف سَراحهم أخيرًا لم يكن هناك وقت للنوم.''',
    '''تُرى أيكون هذا الفون … رابيك مثله؟ وسواء كان مثله أم لم يكن، فليس ثمة حيلة. بدَّل الضباط ملابسهم، ورتَّبوا هِندامهم، وانطلقوا جميعًا يبحثون عن دار الإقطاعي. وفي الميدان أمام الكنيسة قيل لهم إنه يمكن الذهاب إلى دار السادة من الأسفل … أن يهبطوا من خلف الكنيسة إلى النهر ويسيروا على الشاطئ حتى يبلغوا بستان الدار، وهناك ستقودهم دروبها إلى حيث يريدون، أو أن يذهبوا من أعلى … من الكنيسة مباشرة، على الطريق الذي يُفضي بعد نصف فرسخ من القرية إلى مخازن السادة مباشرة. وقرَّر الضباط أن يتبعوا الطريق العلوي.''',
    '''وتساءلوا في أثناء الطريق: من هو فون … رابيك هذا؟ أليس هو الذي كان يقود فرقة الخيَّالة «س» قرب بليفيا؟''',
    '''– كلا، لم يكن فون … رابيك، بل رابي، وبدون فون.''',
    '''– ما أروع الطقس!''',
    '''وتفرَّع الطريق عند أول مخزن من مخازن السادة، فاتجه فرع منه إلى الأمام مباشرةً حيث اختفى في ظلام المساء، بينما انعطف الفرع الثاني إلى اليمين نحو منزل السادة. ومضى الضباط يمينًا وراحوا يتحدَّثون بصوت خافت … وعلى جانبَي الطريق امتدَّت مخازن حجرية بأسقف حمراء، وكانت جهمةً ثقيلة، تشبه كثيرًا ثُكنات مدينة ريفية. وفي الأمام لاحت أضواء نوافذ بيت السادة.''',
    '''وقال أحد الضباط: يا سادة هذا فألٌ حسن! إن كلب صيدنا يسير في مقدمة الجميع؛ إذن فهو يشم رائحة فريسة!''',
    '''سار الملازم لوبيتكو في المقدمة، وكان طويلًا وممتلئ الجسم، ولكنه بلا شوارب على الإطلاق (كان قد جاوز الخامسة والعشرين، ولكن لسبب ما لم ينبت في وجهه المستدير الشبعان أي شعر)، وكان مشهورًا في اللواء بحدسه وقدرته على التكهُّن بوجود نساء عن بعد، فاستدار قائلًا: نعم، هنا ينبغي أن توجد نساء. إنني أُدرك ذلك بغريزتي.''',
    '''واستقبل الضباط عند عتبة الدار فون … رابيك نفسه، وهو شيخٌ بھي، في حوالي الستين، في حلة مدنية. وقال وهو يصافح الضيوف إنه مسرورٌ جدًّا وسعيد، ولكنه يرجو السادة الضباط بشدة ويستحلفهم بالله أن يعذروه على عدم دعوته لهم للمبيت … فقد حضرتْ إليه شقيقتاه وأبناؤهما وإخوته وجيرانه، بحيث لم تبقَ لديه غرفة واحدة خالية.''',
    '''صافح الجنرال أيدي الجميع وهو يرجو المعذرة ويبتسم، ولكن بدا على وجهه أنه لم يكن قط مسرورًا إلى هذا الحد بهؤلاء الضيوف، مثلما كان ذلك الكونت في العام الماضي، وأنه لم يدعُ إليه الضباط إلا لأن اللياقة، حسب رأيه، تقتضي ذلك. وأدرك الضباط أنفسهم، وهم يصعدون الدرج اللين ويُصغون إلى الكونت، أنهم لم يُدعَوا إلى هذا البيت إلا لأن عدم دعوتهم أمر محرج، وعندما رأوا الخدم يسارعون إلى إشعال المصابيح عند المدخل في الأسفل، وفي البهو في الأعلى، خُيِّل إليهم أنهم حملوا معهم إلى هذا البيت الإزعاج والقلق. فهل يمكن أن يكون وجود تسعة عشر ضابطًا غرباء أمرًا محبَّبًا في مكان اجتمع فيه، ربما لمناسبة عائلية أو لاحتفال ما، شقيقتان مع أبنائهما وإخوة وجيران؟''',
    '''وفي الأعلى، عند مدخل القاعة، استقبلَت الضيوف عجوز طويلة ممشوقة، ذات وجه طويل وحاجبَين أسودين، شديدة الشبه بالإمبراطورة أوجين. قالت وهي تبتسم بترحاب ومهابة إنها مسرورة وسعيدة برؤية الضيوف في بيتها، واعتذرت لعدم تمكُّنها هي وزوجها في هذه المرة من دعوة السادة الضباط للمبيت. وبدا من ابتسامتها الجميلة المهيبة، التي كانت تختفي من وجهها على الفور كلما حوَّلته عن الضيوف لأمر ما، أنها رأت في حياتها الطويلة كثيرًا من السادة الضباط، وأنها في شغل عنهم الآن، وإذا كانت قد دعتهم إلى دارها ومضت تعتذر لهم، فإنما تفعل ذلك فقط لأن ترتيبها ووضعها في المجتمع يقتضيان هذا.''',
    '''وفي غرفة الطعام الكبيرة التي دلف إليها الضباط، جلس إلى أحد جانبَي مائدة طويلة حوالي عشرة رجال ونساء، كبار وشُبان، يشربون الشاي. ومن خلف مقاعدهم بدت مجموعة من الرجال تغلِّفهم سحب دخان السيجار الخفيفة. وفي وسطهم وقف شاب نحيل بسالفَين صغيرين أحمرين يتحدَّث عن شيء ما بصوت عالٍ وبالإنجليزية وهو يلثغ. ومن خلف المجموعة بدت من خلال الباب غرفة مضيئة بأثاث أزرق.''',
    '''وقال الجنرال بصوت عالٍ محاوِلًا أن يبدو مرحًا جدًّا: أيها السادة، إنكم من الكثرة بحيث يستحيل تقديمكم. فلتتعارفوا بأنفسكم يا سادة، دون كُلفة!''',
    '''وانحنى الضباط محيين كيفما كان، بعضهم بوجوه جادة للغاية، بل حتى صارمة، والبعض الآخر بابتسامات متكلَّفة، وهم يشعرون جميعًا بالحرج الشديد، وجلسوا لتناول الشاي.''',
    '''كان أكثر الجميع شعورًا بالحرج النقيب ريابوفتش، وهو ضابط صغير الجسم، محني القامة، يضع نظارة، وذو سوالف كسوالف الوَشَق. وبينما كان بعض زملائه يُكسِبون وجوههم ملامحَ الجد، والبعض الآخر يتكلَّف الابتسام، كان وجهه هو، وسوالفه الوَشَقية ونظارته، كأنما تقول: «أنا أكثر ضباط اللواء كله خجلًا، وتواضعًا، وأقلهم تميزًا!» وفي اللحظات الأولى، عندما دخل غرفة الطعام، ثم بعد ذلك، وهو جالس يتناول الشاي، لم يستطع قط أن يركِّز انتباهه على وجهٍ واحد أو شيء واحد؛ فقد امتزجت الوجوه والملابس وأباريق الكونياك المضلَّعة، والبخار المتصاعد من أكواب الشاي، والسلال الخزفية، امتزج ذلك كله في انطباع واحد هائل ألقى في قلب ريابوفتش بالجزع والرغبة في إخفاء رأسه. وكالممثل الذي يواجه الجمهور لأول مرة، كان يرى كل شيء أمام عينيه، إلا أن ما رآه كان عسير الفهم (تسمَّى هذه الحالة لدى الفسيولوجيين ﺑ «العمى السيكولوجي» وذلك عندما يرى الشخص ولا يفهم ما يراه). ولكن بعد مُضي بعض الوقت تأقلم ريابوفتش فعاد إليه بصره وراح يراقب. وكان أول ما أثار انتباهه، كشخص خجول منطوٍ ذلك الشيء الذي كان يفتقده دائمًا؛ أي تلك الجرأة الفائقة للمعارف الجدد. إذ إن فون … رابيك، وزوجته، والسيدتين الكبيرتين، وتلك الفتاة ذات الثوب البنفسجي، والشاب ذا السوالف الحمراء، والذي اتضح أنه الابن الأصغر لرابيك، قد توزَّعوا بين الضباط ببراعة شديدة وكأنما تدرَّبوا على ذلك من قبل، وعلى الفور أثاروا نقاشًا حاميًا لم يكن بوسع الضيوف إلا أن يشاركوا فيه. وراحت الفتاة البنفسجية تؤكِّد بحرارة أن حياة رجال المدفعية أسهل بكثير من حياة الخيَّالة أو المشاة، أمَّا رابيك والسيدتان الكبيرتان فكانوا يؤكِّدون العكس. وبدأ حديث متقاطع. ونظر ريابوفتش إلى الفتاة البنفسجية التي كانت تجادل بحرارة في أمر غريب عنها وغير مثير لاهتمامها أبدًا، وراقب كيف كانت الابتسامات غير الصادقة تظهر على وجهها ثم تختفي.''',
    '''وجذب فون … رابيك وأسرته الضباط إلى الجدال بمهارة، بينما مضَوا في نفس الوقت يراقبون بيقظة أكواب الضباط وأفواههم، وهل يشربون جميعًا، وهل شايهم حلو، ولماذا لا يتناول الضابط الفلاني البسكويت أو لا يشرب الكونياك. وكلما أطال ريابوفتش النظر وأصاخ السمع ازداد إعجابه بهذه الأسرة التي وإن كانت غير صادقة المشاعر إلا أنها رائعة الانضباط.''',
    '''وبعد الفراغ من تناول الشاي اتجه الضباط إلى الصالة. ولم يخِب حدس الملازم لوبيتكو … فقد كان في الصالة كثير من السيدات والنساء الشابات. وكان الملازم — كلب الصيد — واقفًا بالفعل بجوار شقراء شابة جدًّا ترتدي فستانًا أسودًا، وقد انحنى بجسارة كأنما كان يعتمد على سيف غير مرئي، وهو يبتسم ويلعب كتفَيه بدلال. كان في الغالب يقول هراءً ما طريفًا للغاية؛ لأن الشقراء كانت تنظر بتسامح إلى وجهه الشبعان وتتساءل بلا اكتراث: «حقًّا؟» ولو كان كلب الصيد ذكيًّا لمَا توقع مِن هذه اﻟ «حقًّا» اللامبالية أن يقولوا له: «خذها!»''',
    '''ودوَّت أنغام المعزف، وانطلق فالس حزينًا من الصالة عبر النوافذ المفتوحة، ولسبب ما تذكَّر الجميع أن الربيع الآن وراء النوافذ، وأن الليلة أمسية من شهر مايو. وأحسَّ الجميع في الجو برائحة أوراق الحور الشابة والورود والبنفسج. أمَّا ريابوفتش الذي أفصح فيه الكونياك المشروب عن نفسه تحت تأثير الموسيقى، فقد حوَّل بصره إلى النافذة وابتسم، ثم راح يتابع حركات النساء، وبدا له الآن أن رائحة الورود والحور والبنفسج لا تنبعث من البستان بل من وجوه النساء وفساتينهن.''',
    '''ودعا ابن رابيك فتاةً ما نحيلة إلى الرقص ودار معها دورتين. أمَّا لوبيتكو فقد هرول، وهو ينزلق على الباركيه، إلى الفتاة البنفسجية وحلَّق معها في الصالة. وبدأ الرقص.''',
    '''ووقف ريابوفتش بجوار الباب وسط جمهور غير الراقصين وأخذ يراقب. لم يرقص في حياته كلها مرةً واحدة، ولم يتسنَّ له في حياته كلها أن يحتضن خصر سيدة محترمة. كان يُعجبه جدًّا أن يُمسك الشخص بخصر فتاة لا يعرفها على مرأًى من الجميع ويُقدِّم لها كتفه لتضع عليها يدها، إلا أنه لم يستطع قَط أن يتصوَّر نفسه في مكان هذا الشخص. وفي وقت ما كان يحسد شجاعة زملائه وشطارتهم ويَحِزُ ذلك في نفسه.''',
    '''وكان إدراكه بأنه خجول، محني القامة وباهت، وأنه طويل الخصر ووشقي السوالف يترك في نفسه إحساسًا عميقًا بالمهانة، ولكن بمُضي الزمن أصبح هذا الإحساس مألوفًا، ولم يعد الآن، وهو ينظر إلى الراقصين أو المتحدثين بصوت عالٍ، يشعر بالحسد، بل بإعجاب حزين.''',
    '''وعندما بدأت رقصة الكادريل اقترب ابن فون … رابيك الشاب من غير الراقصين ودعا اثنين من الضباط إلى لعب البلياردو. ووافق الضابطان وخرجا معه من الصالة. ولمَّا لم يكن لدى ريابوفتش ما يفعله، وبدافع الرغبة في المشاركة بأي شيء في الحركة العامة، فقد مضى في أثرهم. خرجوا من الصالة إلى غرفة الاستقبال، ثم إلى ممر زجاجي ضيق، ومنه دلفوا إلى غرفة، حيث قفز لدى ظهورهم ثلاثة من الخدم الناعسين من على الكنبة بسرعة. وأخيرًا، وبعد عبور عدد كبير من الغرف، دخل رابيك الشاب والضباط غرفةً غير كبيرة، امتدَّت فيها طاولة البلياردو. وبدأ اللعب.''',
    '''وقف ريابوفتش، الذي لم يمارس في حياته أي لعبة سوى الورق بجوار الطاولة، وراح ينظر بلا اكتراث إلى اللاعبين، أمَّا هم فكانوا يدورون، بسترات مفكوكة الأزرار وبالعصي في أيديهم، وهم يتبادلون القفشات ويصيحون بكلمات غير مفهومة. لم يلحظه أحد من اللاعبين، وأحيانًا فقط، عندما كان أحدهم يضربه بكوعه أو تشتبك عصاه به عفوًا، يستدير إليه ويقول: pardon. وقبل أن ينتهي الدور الأول كان قد أحسَّ بالملل، وبدأ يتخيَّل أنه زائد على الحاجة ويعوقهم … وراودته رغبة في العودة إلى الصالة فخرج.''',
    '''وفي طريق العودة تعرَّض لمغامرة صغيرة؛ فقد انتبه في وسط الطريق إلى أنه يسير إلى غير الجهة التي يقصدها؛ فقد كان يذكر جيدًا أنه ينبغي أن يقابل في الطريق ثلاثة خدم ناعسين، ولكنه عبر خمس أو ست غرف، ولم يقابل الخدم وكأنما انشقَّت الأرض وابتلعتهم. وعندما أدرك خطأه عاد قليلًا إلى الوراء وانعطف يمينًا، فوجد نفسه في غرفة مكتب شبه مظلمة لم يمرَّ بها في طريقه إلى غرفة البلياردو. وقف هنا حوالي نصف دقيقة، ثم فتح بحزم أول باب وقع عليه بصره، وولج غرفةً مظلمة تمامًا. وفي مواجهته مباشرةً ظهر فرج باب كان يتسرَّب منه ضوء ساطع. ومن خلف الباب تناهت نغمات مكتومة لرقصة مازوركا حزينة. وهنا، كما في الصالة، كانت جميع النوافذ مفتوحةً على مصاريعها، وانتشرت رائحة الحور والبنفسج والورود.''',
    '''توقَّف ريابوفتش متردِّدًا … وفي تلك اللحظة فوجئ بخطوات عجلى وحفيف ثوب، وهمس صوت نسائي مختنق: «أخيرًا!» وطوَّقت عنقه ذراعان ناعمتان عَطِرتان، لا شك أنهما نسائيتان. والتصق خد دافئ بخده، وفي نفس اللحظة تردَّد صوت قبلة. وعلى الفور ندت عن صاحبة القبلة صرخة ضعيفة، وارتدَّت عنه، بتقزُّز، كما خُيل لريابوفتش. وكاد هو أيضًا أن يصرخ، واندفع نحو فرج الباب المضيء … عندما عاد إلى الصالة كان قلبه يخفق ويداه ترتعشان بصورة ملحوظة، حتى إنه سارع بإخفائهما وراء ظهره. وفي البداية عذَّبه الخجل والخوف من أن كل من في الصالة يعرفون أن امرأةً قد عانقته وقبَّلته الآن، فانكمش وأخذ يتلفَّت حوله بقلق، وعندما تأكَّد أنهم يرقصون ويُثرثرون بهدوء في الصالة كما في السابق، استسلم تمامًا لهذا الإحساس الجديد الذي لم يمرَّ به في حياته قَط. كان شيء غريب يحدث له … وبدا له أن عنقه الذي طوَّقته منذ لحظات ذراعان ناعمتان عَطِرتان قد تلوَّث بالزيت. وعلى خده، بجوار شاربه الأيسر حيث قبَّلته تلك المجهولة، سرت برودة راعشة خفيفة كبرودة قطرات النعناع، وكلما أمعن في حك هذا الموضع ازداد الإحساس بالبرودة، أمَّا هو فكان مُفعمًا من قمة رأسه إلى أخمص قدميه بهذا الشعور الجديد الغريب الذي كان يتنامى أكثر فأكثر … وأحسَّ برغبة في الرقص والحديث والانطلاق إلى البستان، والضحك بصوت عالٍ … ونسي تمامًا أنه محني القامة، باهت، وأن سوالفه وَشَقية و«هيئته غير محددة» (كما وصفته إحدى النساء في حديث سمعه عرضًا). وعندما مرَّت بجواره زوجة فون … رابيك ابتسم لها ابتسامةً عريضة رقيقة، حتى إنها توقفت ونظرت إليه مستفهمة.''',
    '''فقال وهو يسوِّي نظارته: بيتكم يُعجبني جدًّا!''',
    '''ابتسمت زوجة الجنرال وأخبرته أن هذا البيت كان في زمانه مِلكًا لأبيها، ثم سألته هل والداه على قيد الحياة، ومنذ متى وهو في الخدمة، ولماذا هو نحيل هكذا وغير ذلك من الأسئلة … وبعد أن تلقَّت الإجابة عن أسئلتها استأنفت سيرها، أمَّا هو، فبعد حديثه معها، أصبح يبتسم بصورة أرق ويفكِّر في أنه محاط بأناس رائعين.''',
    '''وعلى العشاء كان ريابوفتش يأكل آليًّا كل ما يقدَّم له ويشرب، ودون أن يصغي إلى شيء، مضى يحاول أن يفسِّر لنفسه تلك المغامرة القريبة … كان لهذه المغامرة طابع غامض ورومانسي، إلا أن تفسيرها كان أمرًا سهلًا. ربما ضربت إحدى الفتيات أو السيدات موعدًا لشخص ما في تلك الغرفة المظلمة، وانتظرته طويلًا، ولمَّا كانت مستثارة الأعصاب فقد ظنَّت ريابوفتش بطلها المنشود. ويبدو ذلك أقرب احتمال، خاصةً أن ريابوفتش، عندما مَر عبر الغرفة المظلمة، توقَّف مترددًا؛ أي إنه كان يبدو كشخص ينتظر أيضًا شيئًا ما … وهكذا فسَّر ريابوفتش لنفسه سبب القبلة التي تلقَّاها.''',
    '''وفكَّر وهو يطوف بوجوه النساء: «ولكن من هي؟ ينبغي أن تكون شابة؛ لأن العجائز لا يذهبن إلى المواعيد الغرامية. ثم إنها مهذبة؛ فقد ظهر ذلك من حفيف ثوبها، ورائحة عطرها، وصوتها …»''',
    '''وتوقَّفت نظراته على الفتاة البنفسجية فأعجبته للغاية. كانت كتفاها وذراعاها جميلتين، ووجهها ذكيًّا، وصوتها رائعًا. وشعر ريابوفتش، وهو يتطلَّع إليها، برغبة في أن تكون هي بالذات، وليس غيرها، تلك المجهولة … ولكنها ضحكت ضحكةً ما غير صادقة، وقطَّبت أنفها الطويل الذي بدا له كأنف العجائز؛ عندئذٍ حوَّل بصره إلى الشقراء ذات الفستان الأسود.''',
    '''كانت أكثر شبابًا وبساطةً وصدقًا، وكان صدغاها ساحرَين، وكانت ترشف الكأس بطريقة جميلة جدًّا. وأراد ريابوفتش الآن أن تكون هي تلك المرأة، ولكنه سرعان ما وجد أن وجهها مسطح، فحوَّل بصره إلى جارتها.''',
    '''وفكَّر وهو يحلم: «من الصعب أن تخمِّن. لو أخذنا من البنفسجية كتفَيها وذراعيها فقط، وأضفنا إليها صدغَي الشقراء، وأخذنا العينين من تلك التي تجلس إلى يسار لوبيتكو، فإن …»''',
    '''وجمع ذلك في ذهنه فظهرت لديه صورة الفتاة التي قبَّلته، تلك الصورة التي أرادها، ولكنه لم يستطع قَط أن يجدها على المائدة.''',
    '''وبعد العشاء مضى الضيوف وقد شبعوا وانتشَوا يُودِّعون ويشكرون. وعاد أصحاب الدار يعتذرون ثانيةً عن عدم استطاعتهم استبقاءهم للمبيت.''',
    '''«مسرور، مسرور جدًّا يا سادة!» قال الجنرال بصدق في هذه المرة (ربما لأن الناس عندما يودِّعون الضيوف يكونون أكثر صدقًا وطيبةً ممَّا عند استقبالهم). «سعيد جدًّا! شرِّفونا بالزيارة في طريق العودة! بلا كُلفة! إلى أين؟ تريدون العودة من أعلى؟ كلا، اذهبوا عبر البستان، في الأسفل؛ فهناك أقرب.»''',
    '''خرج الضباط إلى البستان، وبعد الضوء الساطع والصخب بدا لهم البستان مظلمًا وهادئًا للغاية. وساروا إلى باب السور في صمت. كانوا شبه سكارى، مَرِحين، راضين، ولكن الظلام والسكون جعلاهم يخلدون لحظةً إلى التفكير. وتبادرت إلى ذهن كل منهم، كما إلى ذهن ريابوفتش، في الغالب نفس الفكرة: تُرى هل سيأتي ذلك اليوم الذي سيكون لديهم، كما لدى رابيك، منزل كبير، وأسرة، وبستان، وتُصبح لديهم أيضًا إمكانية ملاطفة الضيوف، ولو عن غير صدق، وجعلهم شِباعًا، سُكارى، راضين؟ وعندما خرجوا من باب السور تحدثوا جميعًا على الفور، وراحوا يضحكون بصوت عالٍ دونما سبب. كانوا الآن يسيرون على الدرب الذي ينحدر إلى النهر ثم يمتد بجوار المياه مباشرةً ملتفًّا حول دغل الشاطئ والخلجان الصغيرة وأشجار الصفصاف ذات الأغصان المهدَّلة فوق الماء. كان الشاطئ والدرب لا يكادان يلوحان، أمَّا الشاطئ الأخر فغرق كله في الظلمة، وفي بعض الأماكن انعكست النجوم على سطح المياه المظلمة. كانت ترتعش وتتلاشى، ومن هذا وحده كان يمكن التخمين بأن النهر يتدفَّق بسرعة. وكان الهدوء يشمل المكان. وعلى الشاطئ الآخر أنَّت طيور البكاسين الناعسة، أما على هذا الشاطئ فقد صدح بلبل بصوت عالٍ في إحدى الخمائل غير عابئ بجمهرة الضباط. وتوقف الضباط بجوار الخميلة، وتحسسوها، بينما ظل البلبل يصدح.''',
    '''وسُمعت صيحات استحسان: هل رأيتم؟ نحن نقف بجواره وهو لا يعيرنا انتباهًا! يا له من شيطان!''',
    '''في نهاية المشوار صعِد الدرب إلى أعلى والتقى بالطريق قرب سور الكنيسة، وهنا جلس الضباط وقد أرهقهم الصعود، ودخَّنوا. وعلى الشاطئ الآخر لاح ضوء أحمر كابٍ، ولما لم يكن لديهم ما يفعلونه أخذوا يخمنون هل هي شعلة نار، أم ضوء في نافذة، أم شيء آخر … وتطلع ريابوفتش أيضًا إلى الضوء، وخُيل إليه أنه يبتسم له ويغمز بطريقة خاصة وكأنما يعرف أمر القبلة.''',
    '''وعندما عاد ريابوفيتش إلى مسكنه نزع ملابسه بسرعة وأوى إلى الفراش، وفي نفس المنزل نزل معه لوبيتكو والملازم ميرزلياكوف، وهو فتًى هادئ، صموت، يُعتبر في محيطه ضابطًا مثقفًا، يقرأ دائمًا في كل مكان يمكن فيه القراءة مجلة «بشير أوروبا» التي كان يحملها معه أينما ذهب. ونزع لوبيتكو ملابسه وأخذ يروح ويجيء في الغرفة طويلًا، وبدا كشخص غير راضٍ، ثم أرسل جندي المراسلة ليُحضر بيرة. وأوى ميرزلياكوف إلى الفراش، ووضع بجوار رأسه شمعة، وانهمك في قراءة «بشير أوروبا».''',
    '''«تُرى من هي؟» فكَّر ربابوفتش وهو ينظر إلى السقف المسوَد من الدخان.''',
    '''كان لا يزال يُخيل إليه أن عنقه ملوث بالزيت، وبجوار فمه أحس بالبرودة الخفيفة كبرودة قطرات النعناع. وومضت في خياله كتفا الفتاة البنفسجية وذراعاها، وصدغا الشقراء ذات الفستان الأسود وعيناها الصادقتان، والخصور والفساتين والبروشات. وحاول أن يركِّز انتباهه في هذه الصور، إلا أنها كانت تقفز وتتلاشى وتومض. وعندما كانت هذه الصور تختفي تمامًا على الخلفية السوداء العريضة التي يراها كل من يغمض عينيه، يسمع خطواتٍ عجلى، وحفيف فستان وصوت قبلة، فتتملَّكه فرحة قوية لا سبب لها … وسمع وهو مستسلم لهذه الفرحة كيف عاد جندي المراسلة وأبلغ أنه لا توجد بيرة. واستشاط لوبيتكو غضبًا وعاد يروح ويجيء، وقال وهو يتوقف تارةً أمام ريابوفتش وتارةً أمام ميرزلياكوف: ما رأيكم في هذا الأبله؟ أي أحمق وغبي ينبغي أن يكون حتى لا يجد بيرة؟! هه؟ أليس محتالًا؟''',
    '''فقال ميرزلياكوف دون أن يرفع عينيه عن «بشير أوروبا»: بالطبع لا يمكن أن تجد بيرةً هنا.''',
    '''فألحَّ عليه لوبيتكو: نعم؟ أهكذا تظن؟ يا إلهي، يا ربي، لو ألقيت بي إلى القمر فسأجد لك على الفور بيرةً ونساءً! حسنًا، سأذهب الآن وأجد … فلتعتبرني نذلًا إن لم أجد!''',
    '''واستغرق وقتًا طويلًا في ارتداء ملابسه وشد حذائه الطويل الكبير، ثم دخَّن سيجارةً في صمت ومضى.''',
    '''ودمدم وهو يتوقَّف في المدخل: رابيك، جرابيك، لابيك. يا للشيطان! لا أشعر برغبة في الذهاب بمفردي. يا ريابوفتش، ألَا تريد أن تتريَّض قليلًا؟ هه؟''',
    '''وعندما لم يسمع ردًّا عاد ونزع ملابسه ببطء وأوى إلى الفراش. وتنهد ميرزلياكوف، ووضع «بشير أوروبا»، جانبًا، وأطفأ الشمعة.''',
    '''ودمدم لوبيتكو وهو يشعل سيجارةً في الظلام: نعم …''',
    '''وتغطَّى ريابوفتش إلى ما فوق رأسه، وانطوى على نفسه كالكعكة وراح يجمع في خياله الصور الوامضة ويركِّب منها صورةً متكاملة، إلا أنه لم يوفَّق إلى شيء. وسرعان ما نام، وكانت آخر فكرة طافت بذهنه أن شخصًا ما قد لاطفه وأبهجه، وأن شيئًا ما قد وقع في حياته، شيئًا أحمق ولكنه حسن وبهيج إلى أقصى حد. ولم تفارقه هذه الفكرة حتى في المنام.''',
    '''عندما استيقظ لم يعد يشعر بالزيت على عنقه وبالبرودة النعناعية قرب شفتيه، ولكن الفرحة، مثلما بالأمس، كانت تغمر قلبه كالموجة. وتطلع بإعجاب إلى أُطر النوافذ التي ذهَّبتها الشمس البازغة، وأصاخ السمع إلى الحركة الدائرة في الخارج. كان هناك من يتحدث بصوت عالٍ تحت النوافذ مباشرة.''',
    '''كان قائد بطارية ريابوفتش، ويُدعى ليبيديتسكي، الذي لحق بالبطارية لتوه، يتحدث مع رقيبه بصوت عالٍ جدًّا لعدم تعوُّده على الحديث بصوت خافت.''',
    '''صاح القائد: وماذا أيضًا؟''',
    '''– عند تغيير الحدوات بالأمس يا صاحب المعالي ركَّبنا حدوات ﻟ «عزيز»، ووضع الحكيم له طينًا وخلًّا، والآن يسحبونه من اللجام بدون حمولة. وبالأمس أيضًا يا صاحب المعالي شرب الأسطى أرتيمييف حتى السكر، وأمر الملازمُ بأن نحمله على مقدمة عربة المدفع الاحتياطية.''',
    '''وأبلغ الرقيب أيضًا أن كاربوف نسي خيوط الأبواق الجديدة وأوتاد الخيام، وأن السادة الضباط كانوا مساء الأمس في ضيافة الجنرال فون … رابيك. وخلال الحديث ظهر في النافذة رأس ليبيديتسكي بلحيته الحمراء، وزرَّ عينيه القصيرتي النظر وهو ينظر إلى الضباط الناعسين وحيَّاهم، ثم سأل: كل شيء على ما يُرام؟ فأجاب لوبيتكو متثائبًا: فرس السرج الرئيسية جرحت عنقها … بالنير الجديد.''',
    '''فتنهَّد القائد، وفكر قليلًّا، ثم قال بصوت عالٍ: إنني أفكِّر في الذهاب إلى ألكساندرا يفجرافوفنا. ينبغي أن أزورها. حسنًا، وداعًا. سألحق بكم في المساء.''',
    '''وبعد ربع ساعة تحرَّك اللواء. وعندما مَر في الطريق بجوار مخازن السادة، نظر ريابوفتش يمينًا إلى البيت. كانت حُصر النوافذ مُسدلة. يبدو أن أهل البيت ما زالوا نائمين.''',
    '''وتلك التي قبَّلت ريابوفتش بالأمس كانت أيضًا نائمة. وأراد أن يتصورها نائمة. النافذة المفتوحة على مصراعَيها في غرفة النوم، والغصون الخضراء المُطلة في هذه النافذة، وبرودة الصباح المنعشة، وأريج الحور والبنفسج والورود، والسرير، والكرسي وعليه الفستان الذي هفهف بالأمس، والحذاء والساعة على الطاولة … كل ذلك تخيَّله بوضوح ودقة، أمَّا ملامح الوجه، والابتسامة الناعسة الرقيقة؛ أي بالضبط ما كان مهمًّا ومميزًا، فقد انزلق من خياله كما ينزلق الزئبق تحت الأصابع. وبعد أن قطعوا نصف فرسخ نظر إلى الوراء؛ كانت الكنيسة الصفراء، والبيت، والنهر، والبستان مغمورةً بالنور. وكان النهر جميلًّا للغاية بشواطئه الخضراء اليانعة وانعكاس السماء الزرقاء فيه وتموُّجه الفضي تحت أشعة الشمس في بعض المواضع. وتطلَّع ريابوفتش لآخر مرة إلى ميستيتشكي وداهَمه الحزن، كأنما كان يفارق شيئًا قريبًا حبيبًا.''',
    '''وعلى الطريق لم يكن أمام بصره سوى الصور المألوفة من زمان وغير الشائقة … فعن اليمين وعن اليسار حقول الجودار الفَتِي والحنطة السوداء بالغربان القافزة فيها. فإذا نظرت أمامك رأيت الغبار ومؤخرات الرءوس، وإذا نظرت إلى الخلف ترى نفس الغبار والوجوه … وفي مقدمة الجميع يسير أربعة أشخاص بسيوف … إنهم الطليعة. ومن خلفهم جمع المنشدين، ومن خلف المنشدين نافِخو الأبواق على متن الخيول. وكانت الطليعة والمنشدون، مثل حاملي المشاعل في مواكب الجنائز، ينسون بين الحين والحين المسافة المنصوص عليها في اللوائح، فيبتعدون كثيرًا إلى الأمام … وكان ريابوفتش بجوار المدفع الأول في البطارية الخامسة؛ ولذلك فهو يرى كل البطاريات الأربع السائرة أمامه. وبالنسبة لشخص غير عسكري يبدو هذا الطابور الطويل الثقيل الذي يمثِّله لواء مدفعية متحرك، خليطًا معقَّدًا وصعب الفهم. فليس مفهومًا لماذا يتجمهر هذا العدد من الأشخاص حول مدفع واحد، ولماذا يجره كل هذا العدد من الخيول الملفوفة بعدة غريبة، وكأنما هذا المدفع بالفعل رهيب وثقيل إلى هذه الدرجة. أمَّا بالنسبة لريابوفتش فكل شيء مفهوم؛ ولهذا فهو غير طريف على الإطلاق. إنه يعرف منذ زمن بعيد لماذا يسير في مقدمة كل بطارية، بجوار الضابط، صف ضابط رزين ولماذا يُسمى «الشداد». ومن خلف ظهر هذا الصف ضابط يبدو ساسة خيول الشدة الأولى والوسطى. ويعرف ريابوفتش أن الخيول اليسرى، والتي يركبونها تُسمى السروجية، أمَّا الخيول اليمنى فتُسمى المقودة، وهذا غير طريف أبدًا. ومن وراء السائس تأتي الفرَسان الرئيسيتان.''',
    '''ويمتطي السائس صهوة إحداهما وعلى ظهره غبار الأمس، وعلى ساقه اليمنى خشبة خرقاء مضحكة جدًّا. ويعرف ريابوفتش الغرض من هذه الخشبة، ولا تبدو له مضحكة. وجميع الساسة، عن بكرة أبيهم، يُلوِّحون بالسياط بطريقة آلية وأحيانًا يصيحون. أمَّا المدفع فيبدو قبيحًا؛ فعلى مقدمة عربته تتكوَّم أجولة الشعير المغطاة بالمشمع، بينما تتدلى منه غلايات الشاي وأكياس الجنود والصُّرر الصغيرة، ويبدو كحيوان صغير أليف لا يعرف لأي غرض أحاط به الناس والخيول. وعلى جانبَي المدفع يسير ستة من أفراد الطاقم وهم يهزُّون أذرعتهم. وبعد المدفع يظهر ثانيةً «شدادون» جدد، وساسة، وخيول رئيسية، ثم يتبعهم مدفع آخر، أيضًا قبيح وغير مهيب كالمدفع الأول. وبعد المدفع الثاني يأتي الثالث، والرابع، وبجوار الرابع ضابط، وهكذا دواليك. ويضم اللواء ست بطاريات، في كل بطارية أربعة مدافع. ويمتد الطابور نصف فرسخ، وينتهي بالحملة، التي تسير بجوارها سحنة لطيفة إلى أقصى حد، وقد طأطأت رأسها مستغرقة … إنه الحمار «مجار»، الذي أتى به أحد قادة البطاريات من تركيا.''',
    '''تطلَّع ريابوفتش بلا اكتراث إلى الأمام وإلى الخلف، إلى مؤخرات الرءوس وإلى الوجوه. ولو كان في حال أخرى لاستسلم للنعاس، ولكنه الآن غارق في أفكاره الجديدة السارة؛ ففي البداية، عندما بدأ اللواء تحرُّكه، أراد أن يقنع نفسه بأن حادث القبلة لا يمكن أن يكون طريفًا إلا باعتباره مغامرةً صغيرة غامضة، وأنه في الواقع حادث تافه، ومن الغباء، على أقل تقدير، التفكير فيه جديًّا. إلا أنه سرعان ما ترك عنه المنطق واستسلم للأحلام … فتارةً يتخيَّل نفسه في غرفة الجلوس في دار رابيك، جالسًا بجوار فتاة تشبه الفتاة البنفسجية والشقراء ذات الفستان الأسود، وتارةً يغمض عينيه فيرى نفسه مع أخرى، غير معروفة له أبدًا، بملامح غير محدَّدة إطلاقًا. وكان يتحدث في سره، ويلاطف، ويميل إلى الكتف، ويتخيل الحرب والفراق، ثم اللقاء والعشاء مع الزوجة، والأولاد.''',
    '''«إلى الإستندات!»١ كانت هذه الصيحة تتردَّد كلما انحدر الطريق إلى أسفل.''',
    '''فكان هو أيضًا يصيح: «إلى الإستندات!» ويخشى أن تقطع هذه الصيحة عليه أحلامه وتعيده إلى الواقع.''',
    '''وعندما مروا بجوار ضيعة أحد الإقطاعيين تطلع ريابوفتش عبر الحديقة الصغيرة إلى البستان. ووقعت عيناه على ممر طويل مستقيم كالمسطرة، مفروش بالرمل الأصفر وقد غُرست على جانبيه أشجار بتولا فتية … وبنهمِ شخص أوغل في الأحلام تخيَّل ساقين نسائيتين تخطوان على الرمل الأصفر، ودون أن يتوقع تمامًا ارتسمت في خياله بوضوح تلك التي قبَّلته، والتي استطاع أن يتصوَّرها بالأمس في أثناء العشاء. وتوقفت هذه الصورة في ذهنه ولم تبرحه.''',
    '''وفي منتصف النهار، ترددت صيحة في المؤخرة قرب الحملة: انتباه! إلى الشمال انظر! السادة الضباط!''',
    '''وفي عربة يجرها زوج من الخيول البيضاء، مَر الجنرال قائد اللواء، وتوقف بجوار البطارية الثانية، وصاح بشيء لم يفهمه أحد، وهرول إليه عدة ضباط، ومن بينهم ريابوفتش.''',
    '''وسأل الجنرالُ وهو يطرف بعينين حمراوين: هه، كيف الحال؟ ماذا؟ هل هناك مرضى؟ وبعد أن سمع هذا الجنرال الصغير الرفيع الرد على الأسئلة، مضغ قليلًا، وفكَّر، ثم قال مخاطبًا أحد الضباط: سائس الشدة الرئيسية في المدفع الثالث لديك خَلَع وقاء الركبة وعلَّقَه، هذا الوغد، على عربة المدفع. وقِّع عليه جزاءً.''',
    '''ورفع عينيه إلى ريابوفتش واستطرد: أمَّا أنت، على ما أظن، فسيور الصدر عندك طويلة.''',
    '''وبعد أن أبدى الجنرال بعض الملاحظات الأخرى المملة، تطلَّع إلى لوبيتكو وضحك ضحكةً قصيرة.''',
    '''وقال: أما أنت يا ملازم لوبيتكو فمنظرك اليوم حزين جدًّا.''',
    '''هل أوحشتك لوبوخوفا؟ هه؟ يا سادة، لقد أوحشته لوبوخوفا!''',
    '''كانت لوبوخوفا سيدةً بدينة، طويلة جدًّا، قد تجاوزت الأربعين منذ زمن بعيد. ولمَّا كان الجنرال مولَعًا بالسيدات ذوات الأجساد الضخمة، مهما كان عمرهن، فقد كان يتوهَّم في ضباطه أيضًا هذا الولع. وابتسم الضباط باحترام. وقهقه الجنرال بصوت عالٍ وقد أرضاه أنه قال شيئًا مضحكًا جدًّا ولاذعًا، ثم لمس ظهر الحوذي ورفع يده بالتحية.''',
    '''واستأنفت العربة سيرها.''',
    '''وفكَّر ريابوفتش وهو ينظر إلى سُحب الغبار الراكضة خلف عربة الجنرال: «إن كل ما أحلم به الآن، وما يبدو مستحيلًا وسماويًّا، هو في الواقع عادي جدًّا. كل هذا عادي جدًّا والجميع يُخبرونه … مثلًا هذا الجنرال … قد أحبَّ في زمانه، وهو الآن متزوج ولديه أولاد. والنقيب فاختير متزوج أيضًا ومحبوب، رغم أن قفاه قبيح جدًّا وأحمر، وليس لديه خصر … وسلمانوف فظ وتتري جدًّا، ولكنه عاش أيضًا قصة غرام انتهت بالزواج … وأنا مثلي مثل الآخرين، وسأُخبر عاجلًا أم آجلًا ما خبَّروه …»''',
    '''وأسعدته ورفعت من معنوياته فكرة أنه شخص عادي وأن حياته عادية. ومضى بجرأة، وكيفما شاء، يرسم حياته وسعادته، ولم يضَع أي قيود على خياله.''',
    '''وعندما بلغ اللواء في المساء المكان المنشود، وأخلد الضباط إلى الراحة في الخيام، جلس ريابوفتش ولوبيتكو وميرزلياكوف حول صندوق يتناولون العشاء. كان ميرزلياكوف يأكل على مهل ويمضغ بطء وهو يقرأ «بشير أوروبا» الموضوعة على ركبتيه. وكان لوبيتكو يتحدَّث بلا توقف ويملأ كأسه بالبيرة كلما فرغ، أمَّا ريابوفتش الذي امتلأ رأسه بالضباب من الأحلام طوال النهار فكان يشرب في صمت. وبعد ثلاثة أكواب انتشى وخار، واستبدَّت به رغبة جارفة في الإفضاء لرفاقه بما يُحسه.''',
    '''وبدأ يحكي محاولًا أن يُضفي على صوته نبرةً لا مبالية هازئة: وقعت لي حادثة عند آل رابيك هؤلاء … فقد توجهت هناك إلى غرفة البلياردو …''',
    '''وراح يحكي بالتفصيل حادثة القبلة ثم صمت بعد دقيقة … فقد روى في هذه الدقيقة كل شيء، وأدهشه للغاية أن الرواية لم تتطلَّب إلا هذا الوقت القصير. كان يُخيَّل إليه أنه يستطيع أن يحكي عن القبلة حتى الصباح. وبعد أن استمع إليه لوبيتكو، الذي كان يكذب كثيرًا ولهذا لم يكن يصدِّق أحدًا، نظر إليه بارتياب ثم ضحك ضحكةً قصيرة.''',
    '''أما ميرزلياكوف فلعَّب حاجبيه، ثم قال بهدوء شديد، ودون أن يحوِّل بصره عن «بشير أوروبا»: الله يعلم ما هذا! … ترتمي على عنقه قبل أن تناديه … يبدو أنها مضطربة العقل.''',
    '''فقال ريابوفتش موافقًا: نعم، يبدو أنها مضطربة العقل …''',
    '''وقال لوبيتكو متصنِّعًا الخوف بعينيه: وقع لي حادث مماثل ذات مرة … كنت مسافرًا في العام الماضي إلى كوفنو … ابتعت بطاقة الدرجة الثانية في القطار … وكانت العربة مزدحمةً إلى درجة يستحيل معها أن تجد مكانًا للنوم … فأعطيت للمحصِّل نصف روبل … فأخذ حقائبي وقادني إلى إحدى المقصورات … وأويتُ إلى الفراش وتغطَّيتُ بالبطانية … وكانت المقصورة مظلمة. وفجأةً وجدتُ شخصًا يلمس كتفي وأنفاسه تتردَّد في وجهي. ومددتُ ذراعي فلمستُ مرفق شخص ما … وفتحتُ عيني فرأيتُ امرأة، تصوَّروا! عينان سوداوان، وشفتان حمراوان كسمكة سلمون طيبة، ومنخاران يتنفَّسان بشهوة، وصدر نافر … فقاطعه ميرزلياكوف بهدوء: عفوًا، بخصوص الصدر أستطيع أن أفهم، ولكن كيف استطعت أن ترى لون شفتيها والمقصورة مظلمة؟''',
    '''وأخذ لوبيتكو يراوغ ويسخر من عدم فطنة ميرزلياكوف.''',
    '''وأثار هذا نفور ريابوفتش، فابتعد عن الصندوق، واستلقى، وعاهد نفسه ألَّا يصارح أحدًا بما في نفسه أبدًا.''',
    '''وبدأتْ حياة المعسكر … ومرت الأيام، كل يوم يشبه الآخر كثيرًا. وطوال هذه الأيام كان ريابوفتش يُحس ويفكِّر ويتصرَّف كشخص عاشق. وكل صباح، عندما كان جندي المراسلة يصب له الماء ليغتسل، كان ريابوفتش يتذكر، وهو يغمر رأسه بالماء البارد، أن في حياته شيئًا طيبًا ودافئًا.''',
    '''وفي الأمسيات، عندما يشرع رفاقه في الحديث عن الحب والنساء، كان يُصغي، ويقترب منهم، ويرتسم على وجهه تعبير كالذي يرتسم على وجوه الجنود عندما يسمعون روايةً عن معركة شاركوا فيها هم أنفسهم. أما في الأمسيات التي كان فيها الضباط المنتَشون، وعلى رأسهم كلب الصيد لوبيتكو، يقومون بغزوات دون جوانية على «المحلة»، كان ريابوفتش، المشارك في الغزوات يصبح بعدها حزينًا، ويُحس بشعور عميق بالذنب، ويرجو منها المغفرة في دخيلته … وفي ساعات الفراغ، أو في ليالي الأرق، عندما تواتيه الرغبة في تذكر طفولته وأبيه وأمه، وعمومًا كل ما هو قريب وعزيز، كان يتذكر حتمًا ميستيتشكي أيضًا، والحصان الغريب، ورابيك، وزوجته التي تشبه الإمبراطورة أوجين، والغرفة المظلمة، وفرج الباب الساطع.''',
    '''وفي ٣١ أغسطس غادر المعسكر، ولكن ليس مع اللواء كله، بل مع بطاريتين. وظل طوال الطريق يحلم ويشعر بالاضطراب وكأنما كان عائدًا إلى دياره. واستبدَّت به رغبة جارفة في رؤية الحصان الغريب، والكنيسة، وأسرة رابيك غير الصادقة، والغرفة المظلمة. ولسبب ما همس له «الصوت الداخلي» الذي كثيرًا ما يخدع العاشقين، بأنه حتمًا سيراها … وعذَّبته الأسئلة: كيف سيلقاها؟ وعمَّ سيتحدث معها؟ تُرى ألم تنسَ القبلة؟ وقال لنفسه إنه إذا حدث على أسوأ الأحوال ولم يقابلها، يكفيه سرورًا أنه سيجوس في الغرفة المظلمة ويتذكر.''',
    '''وقُبيل المساء لاحت في الأفق الكنيسة المألوفة والمخازن البيضاء، وخفق قلب ريابوفتش … ولم يسمع ما كان يقوله له الضابط الراكب حصانه إلى جوراه، ونسي كل شيء في الوجود، وأخذ يحدِّق بنهَم في النهر اللامع بعيدًا في الأمام، وفي سقف المنزل، وفي برج الحمام الذي حوَّم الحمام فوقه وقد أضاءته أشعة الشمس الغاربة.''',
    '''وعندما بلغوا الكنيسة، وفيما بعد، وهو يستمع إلى تقرير مسئول الإيواء، كان يتوقع في كل لحظة أن يظهر الفارس من وراء السور ويدعو الضباط إلى تناول الشاي، ولكن … انتهى تقرير مسئول الإيواء، وترجَّل الضباط وتفرقوا في القرية، بينما لم يظهر الفارس …''',
    '''«سيعرف رابيك الآن من الفلاحين أننا وصلنا فيرسل من يدعونا.» فكر ريابوفتش وهو يدلف إلى مسكنه ولا يفهم لماذا يشعل رفاقه شمعةً ويسرع جندي المراسلة إلى تجهيز السماور.''',
    '''واستولى عليه قلق قابض. ورقد، ثم نهض، ونظر من النافذة ليرى هل الرسول قادم أم لا. ولكن الرسول لم يظهر. فرقد ثانية، وبعد ساعة نهض، ولم يستطع مغالبة قلقه فخرج من البيت واتجه نحو الكنيسة. كان الميدان بجوار السور مظلمًا ومقفرًا … ووقف ثلاثة جنود عند المهبط تمامًا وقد لزموا الصمت. وعندما رأوا ريابوفتش انتفضوا وأدَّوا التحية العسكرية، فرفع يده رادًّا التحية ومضى يهبط على الدرب المعروف.''',
    '''كانت السماء كلها فوق الشاطئ الآخر مصبوغةً بلون أحمر؛ فقد بزغ القمر، وكانت ثمة فلاحتان تتحدثان بصوت عالٍ وتسيران في مزرعة الخضراوات وهما تقطفان أوراق الكرنب. ولاحت خلف المزرعة عدة بيوت ريفية متشحة بالسواد … أما على هذا الشاطئ فكان كل شيء مثلما في شهر مايو؛ الدرب، والخمائل، والصفصاف المتدلي فوق الماء … إلا أن ذلك البلبل الشجاع لم يكن يصدح، كما لم تنتشر رائحة الحور والعشب الفتي.''',
    '''وعندما بلغ ريابوفتش البستان أطل من باب السور. كان البستان مظلمًا وهادئًا … ولم تظهر إلا جذوع أشجار البتولا البيضاء القريبة وقسم من الممر، أمَّا ما عدا ذلك فقد اختلط بكتلة الظلام. وأصاخ ريابوفتش وحدَّق بنهم، ولكنه بعد أن وقف حوالي ربع ساعة دون أن يسمع صوتًا أو يرى ضوءًا عاد أدراجه.''',
    '''واقترب من النهر، ولاح أمامه مسبح الجنرال وملاءات بيضاء منشورة على حاجز الجسر … ارتقى الجسرَ ووقف، ودونما داعٍ لمس ملاءة. كانت الملاءة خشنةً وباردة. ونظر إلى الماء في الأسفل … كان النهر ينساب بسرعة ويخرخر بصوت لا يكاد يُسمع بجوار قوائم المسبح. وانعكس القمر الأحمر قرب الشاطئ الأيسر، وركضت أمواج صغيرة فوق انعكاسه وهي تمطُّه وتمزقه قطعًا، وبدا أنها تريد أن تجرفه معها.''',
    '''وفكَّر ريابوفتش وهو يحدِّق في المياه الجارية: «يا للحماقة! يا للحماقة! ما أغبى كل هذا!»''',
    '''الآن، عندما لم يعد ينتظر شيئًا، تبدَّت له حادثة القبلة، ولهفته، والآمال الغامضة، وخيبة الأمل، في ضوء واضح. لم يعد يبدو له غريبًا أن رسول الجنرال لم يأتِ، وأنه لن يرى أبدًا تلك التي قبَّلته صدفةً بدلًا من شخص آخر. بالعكس، كان سيكون غريبًا لو رآها.''',
    '''كانت المياه تتدفَّق إلى جهة غير معلومة ولغرض غير معروف. وتدفَّقت بهذه الصورة أيضًا في شهر مايو. ومن نُهير في مايو تحوَّلت إلى نهر كبير، ومن نهر إلى بحر، ثم تبخَّرت، وتحوَّلت إلى مطر، وربما كانت الآن، نفس تلك المياه، هي التي تتدفق ثانيةً أمام عيني ريابوفتش … فما الداعي؟ ولأي غرض؟''',
    '''وبدت له الدنيا كلها والحياة كلها مزحةً غير مفهومة وبلا معنًى … وعندما حوَّل عينيه عن المياه وتطلَّع إلى السماء، تذكر ثانيةً كيف لاطفه القدر عرضًا في شخص المرأة المجهولة، وتذكر أحلامه الصيفية وصوره، فبدت له حياته شحيحةً للغاية وبائسةً ولا لون لها.''',
    '''وعندما عاد إلى مسكنه لم يجد أحدًا من زملائه.''',
    '''وأخبره جندي المراسلة بأنهم قد ذهبوا جميعًا إلى «الجنرال فون ترابكين» الذي بعث رسولًا لدعوتهم … وللحظة توهجت الفرحة في قلب ريابوفتش، إلا أنه أخمدها على الفور، واستلقى في الفراش، وكيدًا في حظه، كأنما كان يبغي أن يغيظه، لم يذهب إلى الجنرال.''',
    '''١  إستندة العربة هي العمود الأفقي المتحرك الذي تُشد إليه العربة. (المعرب)''',
  ]), */
  Story(
    text: [
      '''الحسناوان للكاتب أنطون تشيخوف''',
      '''١''',
      '''أذكر أنني ذات مرة، وأنا بعدُ تلميذ في الصف الخامس أو السادس، كنت مسافرًا مع جدي من قرية «بلشایا كریبكايا» في مقاطعة الدون إلى مدينة روستوف على الدون. كان نهارًا من أيام أغسطس القائظة المملة إلى درجة الإرهاق. والتصقت جفوننا وجفَّت حلوقنا من الحر والريح الجافة الساخنة التي كانت تدفع في وجوهنا سُحب الغبار. ولم تكن ثمة أي رغبة في التطلع أو الكلام أو التفكير. وعندما كان سائق العربة النعسان؛ كاربو الأوكراني، يُلوِّح بسوطه على الفَرَس فيقع السوط على عمرتي، لم أكن أحتج أو يندُّ عني صوت، بل كنت أستيقظ من النعاس فأتطلع بكآبة واستكانة إلى الأفق علِّي أرى عبْرَ الغبار قرية. ثم توقفنا لإطعام الخيول في قرية أرمنية كبيرة تُسمَّى «بخش .. صالي» عند أرمني ثري من معارف جدي. لم أرَ في حياتي صورة أكثر كاریكاتيرية من مظهر هذا الأرمني.''',
      '''تصوروا رأسًا صغيرًا حليقًا، بحاجبين كثيفين مهدَّلين إلى أسفل كثيرًا، وبأنف طائر، وبشوارب بيضاء طويلة، وفم واسع تمتد منه قصبة تدخين طويلة من خشب الكرز. وكان هذا الرأس ملتصقًا بصورة غير متقنَة بجذع نحيل أحدب، يرتدي حُلة خيالية: سترة حمراء قصيرة، وسروالًا واسعًا ساطع الزرقة. وكانت هذه القامة تسير مباعدة بين ساقيها وتحكُّ الأرض بحذائها، وتتحدث دون أن تنزع قصبة التدخين من فمها، وتتصرف بعِزة أرمنية أصيلة، فلا تبتسم، وتبحلق بعينيها، وتحاول أن تُولي الضيوف أقل قدر من الاهتمام.''',
      '''ولم يكن في غرف الأرمني ريح ولا غبار، ولكن جوها كان منفِّرًا وخانقًا ومملًّا كما في السهوب وفي الطريق. وأذكر أنني جلست على صندوق أخضر في الركن، وقد غطاني التراب وعذبني القيظ. وانبعثت من الجدران الخشبية غير المطلية ومن الأثاث والأرضية المدهونة بالغراء رائحة خشب جاف أحرقته الشمس .. وذباب، ذباب، ذباب .. حيثما نظرت وجدت ذبابًا. أخذ جدي والأرمني يتحدثان بصوت خافت عن المراعي والأعشاب والغنم .. وكنت أعرف أنهم سيستغرقون ساعة كاملة في إعداد السماور، وأن جدي سيظل يشرب الشاي ما لا يقل عن ساعة، ثم يرقد لينام ساعتين أو ثلاثًا، وأني سأُضَيِّعُ رُبْعَ النهار في انتظارٍ أعود بعده ثانية إلى القيظ والغبار والطرق الحفرية. وأصغيت لهمهمة الصوتين وبدأ يُخَيَّلُ إليَّ أنني أرى منذ زمن بعيدٍ بعيدٍ هذا الأرمني، وصوان الآنية، والذباب، والنوافذ التي تلفحها الشمس اللاهبة، وأنني لن أكفَّ عن رؤيتها حتى في المستقبل البعيد جدًّا، فتملكتني كراهية للسهوب، وللشمس وللذباب.''',
      '''ودخلت امرأة أوكرانية بمنديل رأس تحمل آنية الشاي، ثم أحضرت السماور. وخرج الأرمني على مهل إلى ردهة المَدْخَل وصاح: یا ماشيا! تعالي صُبِّي الشاي! أين أنتِ؟ یا ماشيا!١''',
      '''وتناهی وقع خطوات عجلی، ودخلت الغرفة فتاة في حوالي السادسة عشرة، في فستان بسيط من الشيت، وفي منديل أبيض. وكانت مولية ظهرها إليَّ وهي تغسل الآنية وتصب الشاي، فلم ألحظ إلا أنها دقيقة الخصر، حافية القدمين، وأن كعبَيها الصغيرين العاريين يغطيهما سروال مُسدل.''',
      '''ودعاني رب الدار إلى تناول الشاي. وعندما جلست إلى المائدة تطلعت إلى وجه الفتاة التي ناولتني الكوب، وفجأة أحسست وكأن نسمة هبَّتْ على روحي ونفخت عنها كل انطباعات النهار بمللها وغبارها. رأيت قسمات ساحرة لأروع وجه صادفني من قبل في اليقظة أو راودني في الأحلام. كانت أمامي حسناء، وقد أدركت ذلك من أول نظرة كما أدرك البرق.''',
      '''إنني مستعد أن أقسم بأن ماشا، أو كما دعاها أبوها ماشيا، كانت حسناء بالفعل، ولكني لا أستطيع أن أبرهن على ذلك. وقد يحدث أحيانًا أن تتزاحم السحب عند الأفق في اضطراب، وتحتجب الشمس خلفها فتلونها بشتَّی الألوان:''',
      '''بالأحمر القاني، وبالبرتقالي، وبالذهبي، وبالليلكي، وبالوردي الداكن. وتبدو إحدى السحب كالراهب، والأخرى كالسمكة، والثالثة كالتركي المعمم. ويحتل لهب المغيب ثلث صفحة السماء، ويتوهج علی صلیب الكنيسة وعلى زجاج نوافذ دار السادة، وينعكس في النهر وفي بِرك المياه، ويتذبذب على الأشجار. وبعيدًا على صفحة الشفق يُحلِّق سرب من البط البري ليبيت في مكان ما .. ويتطلع الراعي الذي يسوق البقر، والمسَّاح العابر في عربته فوق السد، والسادة المتنزهون .. يتطلعون كلهم إلى الغروب فيجدونه جميعًا فائق الجمال، ولكن أحدًا لا يعرف ولن يخبرنا بسر جماله.''',
      '''ولم أكن وحدي الذي وجدت الأرمنية جميلة. فقد ظَلَّ جدي، العجوز ذو الثمانين عامًا، هذا الرجل الصارم الطباع، اللامبالي بالنساء ومفاتن الطبيعة، يحدق في ماشا برقة دقيقة كاملة ثم سأل: هل هذه ابنتك يا أفيت نزاریتش؟''',
      '''فأجاب رب الدار: ابنتي. نعم ابنتي.''',
      '''فامتدحها جدي: آنسة طيبة.''',
      '''ولو نظر فنان إلى جمال هذه الفتاة الأرمنية لاعتبره جمالًا كلاسيكيًّا صارمًا. كان بالضبط ذلك الجمال الذي يدخل تمليه في قلبك، من حيث لا تعلم، الثقة بأنك ترى ملامح سوية، وأن الشعر، والعينين، والأنف، والفم والعنق والصدر، وكل حركات هذا الجسد الشاب قد اتحدت كلها في نغمة هارمونية متكاملة، لم تخطئ الطبيعة فيها خطأً صغيرًا واحدًا. ولسبب ما يُخَيَّل إليك أن المرأة المثالية الجمال ينبغي أن يكون لها أنف مثل أنف ماشا بالضبط، أنف مستقیم مُحدودب قليلًا، ومثل هاتين العينين السوداوين الواسعتين، ومثل هذه الرموش الطويلة، وهذه النظرة الساهمة، وأن شعرها الأسود المتموج وحاجبيها مما ينسجم أيضًا مع لون جبينها وخدَّيها الأبيضين الرقيقين، كما تنسجم أعواد القصب الخضراء مع النُّهير الهادئ. وعُنق ماشا الأبيض وصدرها الفتي غير مكتملي التكوين، ولكن يُخَيَّل إليك أن تشكيلهما يتطلب موهبة فنية هائلة. وتتطلع إلى ماشا، وشيئًا فشيئًا تحس بالرغبة في أن تقول لها شيئًا غير عادي، سارًّا، صادقًا، جمیلًا كجمالها.''',
      '''في البداية أحسست بالإهانة والخجل من أن ماشا لا تُعيرني أدنی اهتمام، وتنظر طوال الوقت إلى أسفل. وخُيِّل إليَّ أن هواءً خاصًّا، سعيدًا ومتعاليًا، يفصلها عني ويحميها بغيرة من نظراتي.''',
      '''وفكَّرت بيني وبين نفسي: «هذا لأنني ملوث بالغبار، وملوح البشرة، وأيضًا لأنني ما زلت صبيًّا.»''',
      '''ولكني فيما بعد، وشيئًا فشيئًا، نسيت نفسي واستغرقت تمامًا في الإحساس بالجمال. لم أعد أذكر ملل السهوب والغبار، ولم أعد أسمع طنين الذباب أو أدرك مذاق الشاي بل كنت أشعر فقط بأنه عبر المائدة تقف أمامي فتاة جميلة.''',
      '''ولكن إحساسي بالجمال كان غريبًا. لم تُثِر ماشا فيَّ الرغبة أو الانبهار أو المتعة، بل حزنًا ثقيلًا، وإن كان لطيفًا.''',
      '''كان هذا الحزن مبهمًا، غامضًا كالحلم. ولسبب ما أحسست بالأسى لنفسي، ولجدي، وللأرمني، وللأرمنية الصبية ذاتها، وراودني شعور كأنما فقدنا نحن الأربعة شيئًا مهمًّا وضروريًّا للحياة، شيئًا لن نجده بعد ذلك أبدًا. وجدي أيضًا بدا محزونًا. لم يعد يتحدث عن المراعي والأغنام، بل رَكَنَ إلى الصمت وهو يسترق النظر إلى ماشا بين الحين والحين في تأمل.''',
      '''وبعد تناول الشاي تمدد جدي لينام، أما أنا فخرجت من البيت وجلست على دَرَجِ المَدْخَل. كان البيت، ككل البيوت في «بخشي .. صالي»، يصلى لهب الشمس. لم تكن هناك أشجار أو عرائش أو ظلال. وكان فناء الأرمني الواسع، المُغطَّى بحشائش رِجْلِ الوزة عامرًا بالحركة والمرح رغم القيظ الشديد. فخَلْفَ أحد الأسيجة المنخفضة، التي كانت تخترق الفناء الواسع هنا وهناك، كانت تجري عملية دراس. وحول عمود دُقَّ في وسط البيدر تمامًا دارَ اثنا عشر حصانًا مسرجين صفًّا واحدًا ومُشكلين نصف قطر دائرة طويلًا. وبجوارها سار فلاح أوكراني في صديري طويل وسروال واسع، وهو يفرقع بالسوط ويصيح بنبرة خاصة، وكأنما يريد أن يغيظ الخيول ويتباهی بسلطانه عليها: حا…ا یا ملاعين! حا…ا…ا… إن شاء الله تأخذكم داهية! خائفون؟''',
      '''كانت الخيول الشهب والبيض والبلق، وهي لا تفهم لماذا يجبرونها على الدوران في مكان واحد وهرس سيقان القمح، تركض بلا رغبة، كأنما فقدت قواها، وتهز ذيولها بغضب.''',
      '''وأثارت الريح من تحت قوائمها سُحبًا من التبن الذهبي وحملتها بعيدًا عبر السياج. وبجوار العرمات العالية الجديدة عملت نساء بالمذاري وتحركت عربات، ومن وراء العرمات، في فناء آخر، ركضت دستة من الخيول المماثلة حول عمود آخر، وفرقع أوکراني مماثل بالسوط هازئًا بالخيول.''',
      '''كانت الدرجات التي أجلس عليها ساخنة. ومن الحر ظهرت على عوارض الدرابزين المخلخلة، وعلى أُطر النوافذ هنا وهناك قطرات صمغ الخشب. وتحت الدرجات، وتحت شیش النوافذ، في خطوط الظل، تلاصقت برغشات حمراء. وكانت الشمس تلهب رأسي وصدري وظهري، ولكني لم أشعر بذلك، بل كنت أشعر فقط بأقدام عارية تخطو من خلفي على ألواح الأرضية الخشبية في ردهة المدخل وغرف المنزل. وبعد أن جمعت ماشا آنية الشاي ركضت هابطة على الدرج فهبَّت عليَّ دفقة هواء، وحلَّقت كطائر نحو مبنًى صغير مسود، يبدو أنه المطبخ، حيث تصاعدت رائحة الضأن المشوي وتناهت رطانة أرمنية غاضبة. واختفت في فتحة الباب المظلمة، وظهرت بدلًا منها على العتبة أرمنية عجوز محدودبة، بوجه أحمر وسروال أخضر. كانت العجوز غاضبة تَسُبُّ أحدًا ما. ثم سرعان ما ظهرت ماشا على العتبة، وقد احمرَّت من حرارة المطبخ، حاملة على كتفها رغيفًا كبيرًا من الخبز الأسود. وركضت عَبْرَ الفناء نحو البيدر، وهي تنثني بجمال تحت ثِقَلِ الخبز، وانسلَّت عَبْرَ السياج، وغاصت في سحابة التبن الذهبي، فاختفت وراء العربات. وأنزل الأوكراني الذي كان يسوق الخيول سوطه وصمت، وظل ينظر صامتًا حوالي دقيقة نحو العربات، وعندما مرقت الفتاة الأرمنية ثانية بجوار الخيول وقفزت عَبْرَ السياج شیَّعها بنظراته ثم صاح في الخيول بنبرة كأنما كان في غاية الكدر: فلتخطفكم مصيبة، يا أولاد الأبالسة!''',
      '''وبعد ذلك ظللت أسمع طول الوقت بلا انقطاع وقع أقدامها العارية، وأراها وهي تركض في الفناء بوجه جاد مهموم. كانت تركض تارة على الدَّرَج فتهب عليَّ دفقة هواء، وتارة إلى المطبخ، وتارة إلى البيدر، وتارة إلى البوابة، فلم أكد ألاحق الدوران برأسي کي أتابعها.''',
      '''وكلما لاحت أكثر أمام عيني، ازداد حزني وطأة.''',
      '''وشعرت بالأسى لنفسي، ولها، وللأوكراني الذي كان يُشيِّعها بنظراته في حزن كلما ركضت إلى العربات خلال سحابة التبن. تُرى أكان ما أشعر به غيرة من جمالها، أم أنني کنت آسى لأن هذه الفتاة ليست فتاتي ولن تكون أبدًا، وأنني بالنسبة لها غريب، أم أنني كنت أشعر شعورًا مُبهمًا بأن جمالها النادر شيء عارض، لا حاجة إليه، وككل ما في الدنيا زائل، أم ربما كان حزني هو ذلك الإحساس الخاص الذي يثيره في الإنسان تأمل الجمال الحقيقي؟ الله أعلم!''',
      '''مرَّت ساعات الانتظار الثلاث دون أن أشعر. وخُيِّلَ إليَّ أنني لم أكد أشبع من تملي ماشا، حتی کان کاربو قد ذهب إلى النهر وحمَّمَ الفَرَس وبدأ يسرجها. وكانت الفَرَس المبتلة تنخر من السرور وتضرب العدة بحوافرها. وکاربو يصيح فيها: «ارجعي!» واستيقظ جدي. وفتحت لنا ماشا البوابة ذات الصرير، وجلسنا في العربة وخرجنا من الفناء. وسرنا في صمت كأنما كان كل منَّا غاضبًا من الآخر.''',
      '''وعندما لاحت روستوف وناخیتشيفان بعد ساعتين أو ثلاث، التفت کاربو بسرعة، بعد أن ظَلَّ طوال الوقت صامتًا، وقال: يا لها من فتاة رائعة لدى الأرمني!''',
      '''وألهب الفرس بالسوط.''',
      '''٢''',
      '''في مرة أخرى، وقد أصبحتُ طالبًا، كنتُ مسافرًا بالقطار إلى الجنوب. كان ذلك في شهر مايو وفي إحدى المحطات، أظن بين بيلجورود وخاركوف، خرجتُ من العربة لأتمشى على الرصيف.''',
      '''كانت ظلال الغروب ترتمي على حديقة المحطة، وعلى الرصيف وعلى الحقل. وحجب مبنى المحطة المغيب، غير أنه ظهر من قمم سُحب الدخان المتصاعدة من القاطرة والمصبوغة بلون وردي رقيق أن الشمس لم تغب بعد.''',
      '''ولاحظت وأنا أتمشَّى على الرصيف، أن معظم الركاب المتجولين يتمشون ويتوقفون فقط بجوار عربة واحدة من عربات الدرجة الثانية، ويرتسم على وجوههم تعبير كأنما هناك شخصية شهيرة تجلس في العربة. وكان بين الفضوليين بجوار هذه العربة أيضًا رفيقي في الرحلة، وهو ضابط مدفعية، فتًی ذکي، دافئ وظريف، ككل من نتعرف بهم في الطريق صدفة ولفترة قصيرة.''',
      '''وسألته: فيمَ تحدق هنا؟''',
      '''فلم يرد بشيء بل أشار بعينيه إلى إحدى النساء. كانت فتاة شابة، في حوالي السابعة عشرة أو الثامنة عشرة، ترتدي تاییرًا روسیًّا، حاسرة الرأس، تضع على إحدى كتفيها بإهمال مانطو صغيرًا. ولم تكن من الركاب، بل يبدو أنها ابنة ناظر المحطة أو أخته. كانت واقفة بجوار نافذة العربة تتحدث مع راكبة كبيرة السن. وقبل أن أستوعب ما رأته عيناي تملَّكني فجأة ذلك الإحساس الذي راودني في القرية الأرمنية.''',
      '''كانت الفتاة حسناء رائعة، ولم يشك في ذلك أحد، لا أنا، ولا من كانوا يتطلعون معي إليها.''',
      '''ولو وصفت هیئتها، كما هو مُتَّبَع، جزءًا جزءًا، فلن تجد فيها جميلًا بالفعل سوى شعرها الأشقر المتموج الغزير المسدل والمعقود على الرأس بشريط أسود، أمَّا عدا ذلك من الملامح فكانت إما غير سوية، وإما عادية للغاية. وربما بسبب طريقتها الخاصة في التدلل، أو لقصر نظرها كانت عيناها مزرورتين، وأنفها مشرئبًا بتقاعس، وفمها صغيرًا، وكان بروفيلها مرسومًا بخطوط واهنة متراخية، وكتفاها ضيقتين بما لا يتفق وسنها، ومع ذلك كانت الفتاة تترك انطباعًا بحسناء حقيقية، وتأكدتُ وأنا أتطلع إليها أن الوجه الروسي، لكي يبدو رائعًا، ليس بحاجة إلى تقاطيع سوية صارمة، بل الأكثر من ذلك أنه لو كان للفتاة، بدلًا من أنفها المشرئب، أنف آخر سوي وخالٍ من عيوب التكوين، كأنف الفتاة الأرمنية، فربما فَقَدَ وجهها بسبب ذلك كل روعته.''',
      '''كانت الفتاة وهي واقفة بجوار النافذة تتحدث وتنكمش من رطوبة المساء، تلتفت إلينا بين الحين والحين، وتارة تنثني واضعة يدها في خصرها، وتارة ترفع يديها إلى رأسها لتُسوِّي شعرها، وكانت تتحدث وتضحك، وترسم على وجهها الدهشة حينًا والرعب حينًا آخر، ولم أذكر لحظة رَكَنَ فيها جسدها ووجهها إلى السكون. كان كل سر جمالها وسحره یكمن بالضبط في هذه الحركات الصغيرة، الرشيقة بلا حدود، وفي ابتسامتها، وفي تعابير وجهها، وفي نظراتها السريعة نحونا، وفي الجمع بين الرشاقة الرهيفة لهذه الحركات وبين الصبا والنضارة ونقاء الروح الذي كان يتجلَّى في ضحكها وصوتها، وذلك الضعف الذي نعشقه في الأطفال، والطيور، والغزلان الصغيرة، والأشجار الوليدة.''',
      '''كان جمالًا فَراشيًّا، تنسجم معه تمامًا أنغامُ الفالس وخفقان الأجنحة في البستان والضحك والمرح، ولا يمكن تصوُّره في ارتباط مع الفكر الجاد أو الحزن أو السكينة. وبدا أنه يكفي أن تهبَّ على الرصيف دفقة ریح نشطة أو يسقط المطر کي يذبل هذا الجسد الهش فجأة ويتناثر هذا الجمال النزق كدقيق الأزهار.''',
      '''ودمدم الضابط متنهدًا عندما توجهنا إلى عربتنا بعد أن دقَّ الجرس للمرة الثانية: هكذا ..''',
      '''أما ماذا كانت تعني «هكذا» هذه فلا أستطيع أن أقرر.''',
      '''ربما كان يشعر بالحزن ولا يريد أن يمضي عن الحسناء والمساء الربيعي إلى العربة الخانقة، أو ربما كان، مثلي، يشعر بأسًى غير مفهوم على الحسناء وعلى نفسه وعليَّ، وعلى جميع الركاب الذين جرُّوا أقدامهم بتراخٍ ودون رغبة متوجهين إلى عرباتهم. وعندما مررنا بجوار نافذة المحطة، حيث جلس وراءها إلى جوار جهازه عامل تلغراف شاحب أحمر الشعر، بخصلات عالية ووجه باهت ناتئ الوجنتين، تنهد الضابط قائلًا: أُراهن على أن عامل التلغراف هذا يعشق تلك الحسناء. فأن تعيش في حقل، تحت سقف واحد مع هذا المخلوق الهفهاف ولا تعشقه لشيء فوق طاقة البشر. ويا لها من تعاسة يا صدیقي، یا لها من سخرية أن تكون محني القامة، مشعثًا، رماديًّا، مستقيمًا، وغير غبي، وأن تعشق هذه الفتاة الحسناء اللاهية التي لا تُعيرك أدنى اهتمام! أو … وهذا هو الأسوأ، تصور أن هذا العامل عاشق، وفي الوقت نفسه متزوج، وأن زوجته أيضًا محنية القامة، مشعثة، ومستقيمة مثله .. يا للعذاب!''',
      '''بجوار عربتنا وقف المحصِّل معتمدًا على حاجز البسطة وهو يتطلع إلى الجهة التي كانت الحسناء تقف فيها، وكان وجهه المنهوك الرخو، الشبعان إلى درجة منفرة، والمتعَب من ليالي السهاد واهتزاز العربة، يُعَبِّر عن التأثر والحزن العميق، كأنما كان يرى في الفتاة شبابه وسعادته وصحوه وطهارته وزوجته وأولاده، كأنما كان يندم ويحس بكل كيانه أن هذه الفتاة ليست له، وأنه بشيخوخته المبكرة، وهيئته الخرقاء، ووجهه السمين بعيد عن السعادة الإنسانية العادية، سعادة أي راكب، بُعْدَهُ عن السماء.''',
      '''ودقَّ الجرس لثالث مرة، وترددت الصفارات، فتحرك القطار بكسل، ومَرَقَ من أمام نوافذنا أولًا المحصِّل، فناظر المحطة، ثم البستان، فالحسناء بابتسامتها الساحرة الماكرة كمكر الأطفال.''',
      '''وأخرجتُ رأسي من النافذة ونظرتُ إلى الوراء فرأيتها وهي تُشيِّع القطار بنظراتها ثم تسير على الرصيف مارَّة أمام نافذة عامل التلغراف، وسوَّت شعرها ثم ركضت إلى البستان. ولم يعد مبنى المحطة يحجب الغروب، وبدا الحقل مكشوفًا، إلا أن الشمس كانت قد غربت، وارتمی الدخان سُحبًا سوداء فوق نبتات القمح المخملية الخضراء. وانتشر الحزن في هواء الربيع، وفي السماء المعتمة، وفي العربة.''',
      '''ودخل المحصِّل المذكور العربة وراح يشعل الشموع.''',
      '''١  النطق الصحيح هو: ماشا (تدليل لاسم ماريا). أما كتابته «ماشيا» فهي إشارة من المؤلف إلى لكنة العجوز الأرمني. (المعرِّب)''',
    ],
  ),

